const fixture = http.createServer((request, response) => {
  response.writeHead(200, { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" })
  response.end(request.url === "/big-table" ? bigDataTableHtml : request.url === "/stale-refs" ? staleRefsHtml : bigRowsHtml)
})

async function api(route: string, body?: unknown) {
  const response = await fetch(`${base}${route}`, {
    ...(body === undefined ? {} : { method: "POST", body: JSON.stringify(body) }),
    headers: { authorization, "content-type": "application/json" },
  })
  assert.equal(response.status, 200, route)
  return await response.json() as Record<string, any>
}

async function execute(sessionId: string, code: string, extra: Record<string, unknown> = {}) {
  return await api("/cli/execute", { sessionId, code, createIfMissing: false, ...extra })
}

try {
  await new Promise<void>((resolve, reject) => { fixture.once("error", reject); fixture.listen(fixturePort, "127.0.0.1", resolve) })
  assert.equal((await api("/extension/status")).connected, true)

  // Semantics + single-session timings on 5,000-row layout table and 5,000-row data table.
  await api("/cli/session/new", { id: "snap-single" })
  const dataTableCheck = await execute("snap-single", `
    await page.goto(${JSON.stringify(`${fixtureUrl}/big-table`)});
    const out = await snapshot({ maxItems: 100 });
    const rowOut = await snapshot({ within: "tbody > tr:nth-of-type(3)" });
    const act2Ref = rowOut.match(/button "Act 2" \\[ref=(e\\d+)\\]/)?.[1];
    if (!act2Ref) throw new Error('missing Act 2 ref: ' + rowOut);
    await ref(act2Ref).click();
    const diff = await snapshot({ within: "tbody > tr:nth-of-type(3)", diff: true });
    const fresh = await snapshot({ maxItems: 100 });
    const row3Ref = fresh.match(/link "link 3" \\[ref=(e\\d+)\\]/)?.[1];
    if (!row3Ref) throw new Error('missing link 3 ref: ' + fresh.slice(0, 400));
    await ref(row3Ref).click();
    return { out, rowOut, diff, hash: await page.evaluate(() => location.hash) };
  `)
  assert.equal(dataTableCheck.isError, false, dataTableCheck.text)
  assert.match(dataTableCheck.value.out, /- navigation "Primary" \[10 links, collapsed\]/)
  assert.match(dataTableCheck.value.out, /- table "Table" \[5001 rows\]/)
  assert.match(dataTableCheck.value.out, /- link "link 0"/)
  assert.match(dataTableCheck.value.rowOut, /- row "Row: Row 2 \| Link: link 2 \| Action: Act 2"/)
  assert.equal(dataTableCheck.value.hash, "#r3")
  assert.match(dataTableCheck.value.diff, /\+\s+button "Acted 2"/)

  // Through the sandbox: a ref still on its element works, reads of a stale ref return false, and actions on stale
  // refs fail within a few seconds with what changed.
  const staleRefs = await execute("snap-single", `
    await page.goto(${JSON.stringify(`${fixtureUrl}/stale-refs`)});
    const s = await snapshot();
    const id = (pattern) => s.match(new RegExp(pattern + ' \\\\[ref=(e\\\\d+)'))?.[1];
    await page.addScriptTag({ content: "mutate()" });
    await ref(id('button "Save"')).click();
    const visible = await ref(id('button "Cart, empty"')).isVisible();
    const t0 = performance.now();
    const cart = await ref(id('button "Cart, empty"')).click().then(() => "clicked", (cause) => cause.message);
    const ms = performance.now() - t0;
    const search = await ref(id('button "Search"')).click().then(() => "clicked", (cause) => cause.message);
    return { title: await page.title(), visible, cart, search, ms, hash: await page.evaluate(() => location.hash) };
  `)
  assert.equal(staleRefs.isError, false, staleRefs.text)
  assert.equal(staleRefs.value.title, "saved")
  assert.equal(staleRefs.value.visible, false)
  assert.match(staleRefs.value.cart, /^locator\.click: Error: ref e\d+ is stale: button "Cart, empty" now reads "Cart, 2 items"; call snapshot\(\) again/)
  assert.match(staleRefs.value.search, /ref e\d+ is stale: button "Search" is gone/)
  assert.ok(staleRefs.value.ms < 6_000, `stale ref took ${staleRefs.value.ms}ms`)
  assert.equal(staleRefs.value.hash, "")
  // A longer action timeout from execute's timeoutMs doesn't stretch the stale-ref grace.
  const staleRefsLongTimeout = await execute("snap-single", `
    await page.goto(${JSON.stringify(`${fixtureUrl}/stale-refs`)});
    const s = await snapshot();
    const id = (pattern) => s.match(new RegExp(pattern + ' \\\\[ref=(e\\\\d+)'))?.[1];
    await page.addScriptTag({ content: "mutate()" });
    await ref(id('button "Save"')).click();
    const visible = await ref(id('button "Cart, empty"')).isVisible();
    const t0 = performance.now();
    const cart = await ref(id('button "Cart, empty"')).click().then(() => "clicked", (cause) => cause.message);
    const ms = performance.now() - t0;
    const search = await ref(id('button "Search"')).click().then(() => "clicked", (cause) => cause.message);
    return { title: await page.title(), visible, cart, search, ms, hash: await page.evaluate(() => location.hash) };
  `, { timeoutMs: 120_000 })
  assert.equal(staleRefsLongTimeout.isError, false, staleRefsLongTimeout.text)
  assert.match(staleRefsLongTimeout.value.cart, /is stale: button "Cart, empty" now reads "Cart, 2 items"/)
  assert.ok(staleRefsLongTimeout.value.ms < 6_000, `stale ref took ${staleRefsLongTimeout.value.ms}ms`)

  await execute("snap-single", `await page.goto(${JSON.stringify(`${fixtureUrl}/big`)})`)
  const singleSamples: number[] = []
  for (let i = 0; i < 5; i++) {
    const single = await execute("snap-single", `
      const t0 = performance.now();
      const s = await snapshot();
      return { ms: performance.now() - t0, len: s.length };
    `)
    assert.equal(single.isError, false, single.text)
    assert.ok(single.value.len > 0 && single.value.len < 200_000)
    singleSamples.push(single.value.ms)
  }
  await api("/cli/session/delete", { id: "snap-single" })

  // 8 concurrent sessions × 3 rounds of big-dom-snapshot and warm snapshot().
  const sessions = Array.from({ length: 8 }, (_, index) => `snap-load-${index}`)
  for (const sessionId of sessions) {
    await api("/cli/session/new", { id: sessionId })
  }

  const scenarioMs: number[] = []
  const perSnapshotMs: number[] = []
  for (let round = 0; round < 3; round++) {
    if (round > 0) {
      await Promise.all(sessions.map((sessionId) => execute(sessionId, `await page.goto('about:blank')`)))
    }
    const batch = await Promise.all(sessions.map(async (sessionId) => {
      const started = performance.now()
      const response = await execute(sessionId, `
        await page.goto(${JSON.stringify(`${fixtureUrl}/big`)});
        const t0 = performance.now();
        const s = await snapshot();
        const t1 = performance.now();
        const f = await snapshot({ find: 'Row 4321' });
        const t2 = performance.now();
        return { len: s.length, find: f, snap1Ms: t1 - t0, snap2Ms: t2 - t1 };
      `)
      return { response, elapsedMs: performance.now() - started }
    }))
    for (const { response, elapsedMs } of batch) {
      assert.equal(response.isError, false, response.text)
      assert.ok(response.value.len > 0 && response.value.len < 200_000)
      assert.ok(String(response.value.find).includes("4321"))
      assert.ok(response.value.snap1Ms < 5_000, `snap1 took ${response.value.snap1Ms}ms`)
      assert.ok(response.value.snap2Ms < 5_000, `snap2 took ${response.value.snap2Ms}ms`)
      scenarioMs.push(elapsedMs)
      perSnapshotMs.push(response.value.snap1Ms, response.value.snap2Ms)
    }
  }

  const warmConcurrentMs: number[] = []
  for (let round = 0; round < 3; round++) {
    const batch = await Promise.all(sessions.map((sessionId) =>
      execute(sessionId, `const t0 = performance.now(); const s = await snapshot(); return { ms: performance.now() - t0, len: s.length }`),
    ))
    for (const response of batch) {
      assert.equal(response.isError, false, response.text)
      assert.ok(response.value.ms < 5_000, `concurrent snapshot took ${response.value.ms}ms`)
      warmConcurrentMs.push(response.value.ms)
    }
  }

  for (const sessionId of sessions) {
    await api("/cli/session/delete", { id: sessionId })
  }

  console.log(JSON.stringify({
    semantics: "PASS",
    staleRefMs: Math.round(staleRefs.value.ms),
    singleSnapshotMs: summarize(singleSamples),
    concurrent8x3ScenarioMs: summarize(scenarioMs),
    concurrent8x3PerSnapshotMs: summarize(perSnapshotMs),
    concurrent8x3WarmSnapshotMs: summarize(warmConcurrentMs),
  }))
} finally {
  await scene.stop()
  await new Promise<void>((resolve) => fixture.close(() => resolve()))
  fs.rmSync(root, { recursive: true, force: true })
}

// Headless check of how snapshot refs behave after the page changes, in a plain page with no extension or relay:
//   PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH=<chrome> bun test/snapshot-refs-browser.ts [--browser <chrome>]
// Runs under Bun because it loads cli/src TypeScript directly. The browser is --browser, else
// PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH, else patchright-core's own Chromium.
import assert from "node:assert/strict"
import { parseArgs } from "node:util"
import { chromium, type Page } from "patchright-core"
import { createSnapshotHelpers } from "../src/snapshot.ts"
import { registerRefSelector } from "../src/snapshot/ref-selector.ts"

const { values: options } = parseArgs({ options: { browser: { type: "string" } } })
const executablePath = options.browser || process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH || chromium.executablePath()
const browser = await chromium.launch({ executablePath })
const context = await browser.newContext()
await registerRefSelector(context)

// Each page records clicks in window.clicked and exposes window.mutate() for the change under test. execute runs
// actions with a 30 s timeout, and so does every page here.
async function open(html: string) {
  const page = await context.newPage()
  page.setDefaultTimeout(30_000)
  await page.setContent(`<!doctype html><title>t</title>${html}<script>window.clicked ??= []</script>`)
  const helpers = createSnapshotHelpers(page, { selectors: new Map() })
  const text = await helpers.snapshot()
  const refFor = (line: RegExp): string => {
    const id = new RegExp(`${line.source} \\[ref=(e\\d+)`).exec(text)?.[1]
    assert.ok(id, `no ref for ${line} in:\n${text}`)
    return id
  }
  return { page, helpers, text, refFor }
}
// Patchright evaluates in an isolated world, so page script globals are reached through script tags and the DOM.
const clicked = async (page: Page): Promise<string[]> => {
  await page.addScriptTag({ content: "document.body.dataset.clicked = JSON.stringify(clicked)" })
  return JSON.parse(await page.evaluate(() => document.body.dataset.clicked ?? "[]"))
}
const run = (page: Page, code: string) => page.addScriptTag({ content: code })
async function timed<T>(action: () => Promise<T>): Promise<{ ms: number; value?: T; error?: string }> {
  const started = Date.now()
  try {
    const value = await action()
    return { ms: Date.now() - started, value }
  } catch (error) {
    return { ms: Date.now() - started, error: error instanceof Error ? error.message : String(error) }
  }
}
const fast = (ms: number) => assert.ok(ms >= 2_500 && ms < 6_000, `took ${ms}ms`)
const results: Record<string, string> = {}

try {
  {
    // A control whose name changed fails within the grace period, says what changed and clicks nothing.
    const { page, helpers, refFor } = await open(`<a data-test="shopping-cart-link" role="button" href="#cart" aria-label="Cart, empty" onclick="clicked.push('cart')">cart</a>`)
    const cart = refFor(/button "Cart, empty"/)
    await run(page, `document.querySelector("a").setAttribute("aria-label", "Cart, 2 items")`)
    const result = await timed(() => helpers.ref(cart).click())
    assert.match(result.error ?? "", new RegExp(`^click: Error: ref ${cart} is stale: button "Cart, empty" now reads "Cart, 2 items"; call snapshot\\(\\) again\n`))
    assert.doesNotMatch(result.error ?? "", /page\.locator|\{"/)
    fast(result.ms)
    assert.deepEqual(await clicked(page), [])
    results.renamed = `PASS ${result.ms}ms`
  }

  {
    // A form re-mounted with a new structure fails fast instead of acting on the look-alike "Search" button.
    const { page, helpers, refFor } = await open(`<form id="searchform"><input type="search" aria-label="Search site"><button type="button">Search</button></form>`)
    const box = refFor(/searchbox "Search site"/)
    const button = refFor(/button "Search"/)
    await run(page, `
      const form = document.getElementById("searchform")
      form.innerHTML = '<div><input role="combobox" aria-label="Search site"><span><button type="button" onclick="clicked.push(1)">Search</button></span></div>'`)
    const filled = await timed(() => helpers.ref(box).fill("eiffel"))
    assert.match(filled.error ?? "", new RegExp(`ref ${box} is stale: searchbox "Search site" is now combobox "Search site"; call snapshot\\(\\) again`))
    const result = await timed(() => helpers.ref(button).click())
    assert.match(result.error ?? "", new RegExp(`ref ${button} is stale: button "Search" is gone`))
    fast(result.ms)
    assert.deepEqual(await clicked(page), [])
    results.remount = `PASS ${result.ms}ms`
  }

  {
    // Re-running a click on a "Delete" that opened a confirm dialog never reaches the dialog's own "Delete".
    const { page, helpers, refFor } = await open(`
      <main><button onclick="this.remove(); document.querySelector('dialog').showModal(); clicked.push('delete')">Delete</button></main>
      <dialog><p>Sure?</p><button onclick="clicked.push('confirm')">Delete</button></dialog>`)
    const remove = refFor(/button "Delete"/)
    await helpers.ref(remove).click()
    const again = await timed(() => helpers.ref(remove).click())
    assert.match(again.error ?? "", /is stale: button "Delete" is gone/)
    assert.deepEqual(await clicked(page), ["delete"])
    results.hiddenTwin = `PASS ${again.ms}ms`
  }

  {
    // A twin with the same role and name inside a closed shadow root isn't the ref's element either.
    const { page, helpers, refFor } = await open(`<div id="host"><button onclick="clicked.push('light')">Go</button></div>`)
    const go = refFor(/button "Go"/)
    await run(page, `
      const host = document.getElementById("host")
      host.innerHTML = ""
      const shadow = host.attachShadow({ mode: "closed" })
      shadow.innerHTML = '<span><button>Go</button></span>'
      shadow.querySelector("button").onclick = () => clicked.push("shadow")`)
    const result = await timed(() => helpers.ref(go).click())
    assert.match(result.error ?? "", /is stale: button "Go" is gone/)
    fast(result.ms)
    assert.deepEqual(await clicked(page), [])
    results.closedShadow = `PASS ${result.ms}ms`
  }

  {
    // Reads never throw: polling isVisible() and count() on a stale ref for longer than the grace period keeps
    // returning false and 0, and an aria-hidden control is matched no more than getByRole matched it.
    const { page, helpers, refFor } = await open(`<div><button>Save</button></div><div aria-hidden="true"><button>Hidden</button></div>`)
    const save = refFor(/button "Save"/)
    const hidden = refFor(/button "Hidden"/)
    await run(page, `document.querySelector("button").textContent = "Saved"`)
    const ref = helpers.ref(save)
    const started = Date.now()
    while (Date.now() - started < 4_000) {
      assert.equal(await ref.isVisible(), false)
      assert.equal(await ref.count(), 0)
      await page.waitForTimeout(250)
    }
    assert.equal(await helpers.ref(hidden).count(), 0)
    results.reads = "PASS"
  }

  {
    // Each action gets its own grace period: an earlier miss on the same locator doesn't shorten the next one.
    const { page, helpers, refFor } = await open(`<div><button onclick="clicked.push('save')">Save</button></div>`)
    const ref = helpers.ref(refFor(/button "Save"/))
    await run(page, `const save = document.querySelector("button"); save.textContent = "Saving…"; setTimeout(() => save.textContent = "Save", 5000)`)
    const first = await timed(() => ref.click())
    assert.match(first.error ?? "", /now reads "Saving…"/)
    const second = await timed(() => ref.click())
    assert.equal(second.error, undefined)
    assert.ok(second.ms >= 1_000, `took ${second.ms}ms`)
    assert.deepEqual(await clicked(page), ["save"])
    results.perCallGrace = `PASS ${first.ms}ms then ${second.ms}ms`
  }

  for (const [label, html, line, change] of [
    // A label that reads "Saving…" for 2 s still gets clicked.
    ["savingLabel", `<div><button onclick="clicked.push('clicked')">Save</button></div>`, /button "Save"/,
      `const save = document.querySelector("button"); save.textContent = "Saving…"; setTimeout(() => save.textContent = "Save", 2000)`],
    // So does a control that's gone for 2 s while its form re-mounts.
    ["remountGap", `<div id="root"><form><button type="button" onclick="clicked.push('clicked')">Go</button></form></div>`, /button "Go"/,
      `const root = document.getElementById("root"); const html = root.innerHTML; root.innerHTML = "<p>Loading…</p>"; setTimeout(() => root.innerHTML = html, 2000)`],
    // A ref that still matches but is hidden for longer than the grace period keeps waiting, as before.
    ["hiddenWait", `<div><button onclick="clicked.push('clicked')">Open</button></div>`, /button "Open"/,
      `const open = document.querySelector("button"); open.style.display = "none"; setTimeout(() => open.style.display = "", 5000)`],
    // So does a match covered by an overlay.
    ["overlay", `<button id="go" onclick="clicked.push('clicked')">Go</button>`, /button "Go"/,
      `const overlay = document.createElement("div"); overlay.style.cssText = "position:fixed;inset:0"; document.body.append(overlay); setTimeout(() => overlay.remove(), 4000)`],
  ] as const) {
    const { page, helpers, refFor } = await open(html)
    const id = refFor(line)
    await run(page, change)
    const result = await timed(() => helpers.ref(id).click())
    assert.equal(result.error, undefined, label)
    assert.ok(result.ms >= 1_500, `${label} took ${result.ms}ms`)
    assert.deepEqual(await clicked(page), ["clicked"], label)
    results[label] = `PASS ${result.ms}ms`
  }

  {
    // An action that passes its own timeout waits that long, like a plain locator, instead of failing after 3 s.
    const { page, helpers, refFor } = await open(`<div><button onclick="clicked.push('save')">Save</button></div>`)
    const save = refFor(/button "Save"/)
    await run(page, `const save = document.querySelector("button"); save.textContent = "Saving…"; setTimeout(() => save.textContent = "Save", 4500)`)
    const result = await timed(() => helpers.ref(save).click({ timeout: 10_000 }))
    assert.equal(result.error, undefined)
    assert.ok(result.ms >= 4_000, `took ${result.ms}ms`)
    assert.deepEqual(await clicked(page), ["save"])
    results.explicitTimeout = `PASS ${result.ms}ms`
  }

  {
    // A ref inside a same-origin iframe resolves in that frame, and fails fast there once its control is renamed.
    const frame = `<button onclick="parent.clicked.push('pay')">Pay</button><button onclick="parent.clicked.push('back')">Back</button>`
    const { page, helpers, refFor } = await open(`<iframe title="Checkout" style="width:300px;height:120px" srcdoc="${frame.replaceAll('"', "&quot;")}"></iframe>`)
    const pay = refFor(/button "Pay"/)
    const back = refFor(/button "Back"/)
    await helpers.ref(back).click()
    await run(page, `document.querySelector("iframe").contentDocument.querySelector("button").textContent = "Paid"`)
    const result = await timed(() => helpers.ref(pay).click())
    assert.match(result.error ?? "", new RegExp(`ref ${pay} is stale: button "Pay" now reads "Paid"; call snapshot\\(\\) again`))
    fast(result.ms)
    assert.equal(await helpers.ref(pay).count(), 0)
    assert.deepEqual(await clicked(page), ["back"])
    results.iframe = `PASS ${result.ms}ms`
  }

  {
    // A plain locator keeps Playwright's normal wait: it's still waiting well past the grace period.
    const { page } = await open(`<main></main>`)
    const pending = timed(() => page.locator("#late").click())
    await page.waitForTimeout(6_000)
    await run(page, `const late = document.createElement("button"); late.id = "late"; late.textContent = "Late"; late.onclick = () => clicked.push("late"); document.body.append(late)`)
    const result = await pending
    assert.equal(result.error, undefined)
    assert.ok(result.ms >= 6_000, `took ${result.ms}ms`)
    assert.deepEqual(await clicked(page), ["late"])
    results.plainLocator = `PASS ${result.ms}ms`
  }

  {
    // Refs keep their ids into a snapshot with different options, still scope snapshot({ within }), and stay strict
    // about a page change.
    const { page, helpers, text, refFor } = await open(`<main><button>One</button><button>Two</button></main>`)
    const one = refFor(/button "One"/)
    const smaller = await helpers.snapshot({ maxItems: 1 })
    assert.match(smaller, new RegExp(`button "One" \\[ref=${one}\\]`), `${text}\n---\n${smaller}`)
    assert.match(await helpers.snapshot({ within: helpers.ref(one) }), /button "One"/)
    await page.evaluate(() => history.pushState({}, "", "#moved"))
    assert.throws(() => helpers.ref(one), /Snapshot refs are stale after a page change; call snapshot\(\) again/)
    results.ids = "PASS"
  }

  console.log(JSON.stringify(results))
} finally {
  await browser.close()
}

// Headless check of snapshot root selection and iframe capture in a plain page with no extension or relay:
//   PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH=<chrome> bun test/snapshot-within-browser.ts [--browser <chrome>]
// Runs under Bun because it loads cli/src TypeScript directly; existing harnesses run Node against built output.
// The browser is --browser, else PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH, else patchright-core's own Chromium.
import assert from "node:assert/strict"
import http from "node:http"
import { parseArgs } from "node:util"
import { chromium, selectors } from "patchright-core"
import { createAriaSnapshotHelper, createSnapshotHelpers } from "../src/snapshot.ts"
import { ariaSnapshotWithoutTextControlValues, registerAriaSnapshotSelector } from "../src/snapshot/aria-snapshot.ts"
import type { SnapshotRefRegistry } from "../src/snapshot/types.ts"
import { portFromEnv } from "./support/ports.ts"

const { values: options } = parseArgs({ options: { browser: { type: "string" } } })
const executablePath = options.browser || process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH || chromium.executablePath()
const cdpPort = await portFromEnv("BROWSE_TEST_CDP_PORT")
const browser = await chromium.launch({ executablePath, args: [`--remote-debugging-port=${cdpPort}`] })
const registry = (): SnapshotRefRegistry => ({ selectors: new Map() })

// The iframe fixture: a modal checkout dialog with a cross-origin payment frame (localhost, so Chromium puts it in
// its own process) and a same-origin one, each with a heading, two textboxes, a button and a nested frame.
const frameForm = (title: string, nested = ""): string => `<!doctype html><html><body>
  <h1>${title}</h1>
  <label>Card number<input name="card" aria-label="Card number"></label>
  <label>Expiry<input name="expiry" aria-label="Expiry"></label>
  <button type="button" onclick="this.textContent='Paid'">Pagar</button>
  ${nested}
</body></html>`

let sameOriginFrameUrl = ""
const nestedHtml = frameForm("Nested").replace("Pagar", "Nested")
// A third origin for a frame that never answers, on its own address so it cannot share a renderer with the page.
// macOS has no 127.0.0.2 unless aliased, so fall back to the IPv6 loopback there.
const hungServer = http.createServer((_request, response) => {
  response.writeHead(200, { "content-type": "text/html; charset=utf-8" })
  response.end(`<!doctype html><html><head><script>while (true) {}</script></head><body></body></html>`)
})
await new Promise<void>((resolve, reject) => {
  hungServer.once("listening", () => resolve())
  hungServer.once("error", (error: NodeJS.ErrnoException) => {
    // Bun reports an address the host doesn't have as EADDRINUSE; port 0 can't really be in use.
    if (error.code !== "EADDRNOTAVAIL" && error.code !== "EADDRINUSE") return reject(error)
    hungServer.once("error", reject)
    hungServer.listen(0, "::1")
  })
  hungServer.listen(0, "127.0.0.2")
})
const hungAddress = hungServer.address() as { address: string; family: string; port: number }
const hungHost = hungAddress.family === "IPv6" ? `[${hungAddress.address}]` : hungAddress.address
const hungPort = hungAddress.port
const crossOriginServer = http.createServer((request, response) => {
  response.writeHead(200, { "content-type": "text/html; charset=utf-8" })
  if (request.url === "/nested") return response.end(nestedHtml)
  if (request.url === "/moved") return response.end(frameForm("Moved"))
  if (request.url === "/leak") return response.end(`<!doctype html><html><body><h1>Leaky</h1><input aria-label="Key" value="LEAK-VALUE-CROSS"><button>Go</button></body></html>`)
  if (request.url === "/hung") return response.end(`<!doctype html><html><head><script>while (true) {}</script></head><body></body></html>`)
  if (request.url === "/nested-host") return response.end(`<!doctype html><html><body><h1>A</h1><iframe src="http://${hungHost}:${hungPort}/hung" title="a1"></iframe></body></html>`)
  if (request.url === "/slow") return response.end(`<!doctype html><html><head><script>const end = Date.now() + 1500; while (Date.now() < end) {}</script></head><body><h1>Slow</h1></body></html>`)
  response.end(frameForm("Pay form", request.url === "/payment" ? `<iframe src="${sameOriginFrameUrl}/nested" title="nested" width="200" height="150"></iframe>` : ""))
})
await new Promise<void>((resolve) => crossOriginServer.listen(0, "127.0.0.1", resolve))
const crossOriginPort = (crossOriginServer.address() as { port: number }).port

const hostServer = http.createServer((request, response) => {
  response.writeHead(200, { "content-type": "text/html; charset=utf-8" })
  if (request.url === "/same") return response.end(frameForm("Same form"))
  if (request.url === "/many") return response.end(`<!doctype html><html><body><h1>Many</h1>${Array.from({ length: 10 }, (_, index) => `<iframe src="/same" title="same-${index}"></iframe>`).join("")}</body></html>`)
  if (request.url === "/nested") return response.end(nestedHtml)
  if (request.url === "/moved-frame") return response.end(frameForm("Moved"))
  if (request.url === "/frame-leak") return response.end(`<!doctype html><html><body><h1>Late</h1><input aria-label="Key" value="LEAK-VALUE-ATTR"><button>Go</button></body></html>`)
  if (request.url === "/working") return response.end(`<!doctype html><html><body><h1>Working</h1><input aria-label="Working field" value="working-value"></body></html>`)
  if (request.url === "/mislabel") return response.end(`<!doctype html><html><body><main><h1>Host</h1>
    <div aria-hidden="true"><template shadowrootmode="open"><iframe src="/shadow-frame" title="hidden-host"></iframe></template></div>
    <iframe src="/zero-frame" title="zero" style="border:0;width:0;height:0"></iframe></main></body></html>`)
  if (request.url === "/shadow-frame") return response.end(`<!doctype html><html><body><h1>B frame</h1></body></html>`)
  if (request.url === "/zero-frame") return response.end(`<!doctype html><html><body><h1>A frame</h1></body></html>`)
  if (request.url === "/late-target") return response.end(`<!doctype html><html><body><main><h1>Host</h1><div id="late-slot"></div></main>
    <script>setTimeout(() => { const el = document.createElement("section"); el.id = "late"; el.innerHTML = "<h2>Late</h2>" + Array.from({ length: 12000 }, (_, index) => "<p>row " + index + "</p>").join(""); document.getElementById("late-slot").appendChild(el) }, 1750)</script></body></html>`)
  if (request.url === "/slow-parent") return response.end(`<!doctype html><html><body><main><h1>Host</h1><iframe src="http://localhost:${crossOriginPort}/slow" title="slow"></iframe></main></body></html>`)
  if (request.url === "/aria-many") return response.end(`<!doctype html><html><body><main><h1>Host</h1>
    ${Array.from({ length: 10 }, (_, index) => `<iframe src="/working" title="many-${index}"></iframe>`).join("")}
    ${Array.from({ length: 2 }, (_, index) => `<iframe src="/working" title="tiny-${index}" style="border:0;width:0;height:0"></iframe>`).join("")}
    </main></body></html>`)
  if (request.url === "/nested-hung") return response.end(`<!doctype html><html><body><main><h1>Host</h1>
    <iframe src="http://localhost:${crossOriginPort}/nested-host" title="a"></iframe>
    <iframe src="/working" title="b"></iframe></main></body></html>`)
  if (request.url === "/hung-parent") return response.end(`<!doctype html><html><body><main><h1>Host</h1>
    <iframe src="http://localhost:${crossOriginPort}/hung" title="hung"></iframe>
    <iframe src="/working" title="healthy"></iframe></main></body></html>`)
  if (request.url === "/modal") return response.end(`<!doctype html><html><body><main><h1>Checkout</h1>
    <dialog open aria-modal="true" aria-label="Modal">
      <h2>Details</h2>
      <input aria-label="Email">
      <button type="button">Apply</button>
      <iframe src="/working" title="tiny" width="10" height="10"></iframe>
    </dialog></main></body></html>`)
  if (request.url === "/ads") return response.end(`<!doctype html><html><body><main><h1>Ads</h1>
    ${Array.from({ length: 6 }, (_, index) => `<iframe src="/working" title="ad-${index}" width="300" height="100"></iframe>`).join("")}
    <button type="button">Real action</button></main></body></html>`)
  if (request.url === "/redact-fail") return response.end(`<!doctype html><html><body><main><h1>Host</h1>
    <iframe src="/frame-leak" title="broken"></iframe><iframe src="/working" title="working"></iframe></main></body></html>`)
  response.end(`<!doctype html><html><body><main><h1>Checkout</h1>
    <dialog open aria-modal="true" aria-label="Pagar">
      <iframe src="http://localhost:${crossOriginPort}/payment" title="payment" width="400" height="300"></iframe>
      <iframe src="/same" title="same" width="400" height="300"></iframe>
    </dialog>
  </main></body></html>`)
})
await new Promise<void>((resolve) => hostServer.listen(0, "127.0.0.1", resolve))
const hostPort = (hostServer.address() as { port: number }).port
sameOriginFrameUrl = `http://127.0.0.1:${hostPort}`

const pause = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms))
const refFor = (output: string, role: string, name: string, after?: string): string | undefined => {
  const lines = output.split("\n")
  const start = after === undefined ? 0 : Math.max(0, lines.findIndex((line) => line.includes(after)))
  for (let index = start; index < lines.length; index++) {
    const match = new RegExp(`${role} "${name}" \\[ref=(e\\d+)`).exec(lines[index]!)
    if (match) return match[1]
  }
  return undefined
}

try {
  const page = await browser.newPage()
  // The execute sandbox registers the redaction engine when it connects, before any frame's utility world exists.
  await registerAriaSnapshotSelector(page.context())

  // Each CDP connection gets a default context. Even connections made after the first registration must redact,
  // without a stream of short-lived connections retaining a new selector source per context in Patchright.
  const engines = (selectors as unknown as { _selectorEngines: unknown[] })._selectorEngines
  const initial = engines.length
  for (let index = 0; index < 3; index++) {
    const connection = await chromium.connectOverCDP(`http://127.0.0.1:${cdpPort}`)
    try {
      const field = await connection.contexts()[0]!.newPage()
      await field.setContent('<input aria-label="Account" value="private-marker">')
      const root = field.locator("body")
      const snapshot = await ariaSnapshotWithoutTextControlValues(root, { timeout: 3000 })
      assert.match(snapshot, /textbox "Account"/)
      assert.doesNotMatch(snapshot, /private-marker/)
      assert.match(await root.ariaSnapshot(), /private-marker/)
      await field.close()
    } finally { await connection.close() }
  }
  assert.ok(engines.length <= initial + 1, `${engines.length - initial} retained redaction engines`)

  // Two mains: the first visible one is captured and the output says why.
  await page.setContent(`
    <main><h1>First main</h1><button>Save first</button></main>
    <main><h1>Second main</h1><button>Save second</button></main>
  `)
  const multiple = await createSnapshotHelpers(page, registry()).snapshot({ within: "main" })
  assert.equal(multiple.split("\n")[0], 'within "main" matched 2 elements; showing the first', multiple)
  assert.match(multiple, /button "Save first"/)
  assert.doesNotMatch(multiple, /Save second/)

  // A hidden first match is passed over in favour of the visible one.
  await page.setContent(`
    <main style="display:none"><button>Hidden first</button></main>
    <main><button>Visible second</button></main>
  `)
  const hidden = await createSnapshotHelpers(page, registry()).snapshot({ within: "main" })
  assert.equal(hidden.split("\n")[0], 'within "main" matched 2 elements; showing the first', hidden)
  assert.match(hidden, /button "Visible second"/)
  assert.doesNotMatch(hidden, /Hidden first/)

  // No match: the whole page is captured instead of throwing.
  await page.setContent(`
    <header><h1>No main here</h1></header>
    <section><button>Lonely button</button></section>
  `)
  const missing = await createSnapshotHelpers(page, registry()).snapshot({ within: "main" })
  assert.equal(missing.split("\n")[0], 'within "main" matched nothing; showing the whole page', missing)
  assert.match(missing, /button "Lonely button"/)

  // Exactly one match keeps the old behaviour, with no note.
  await page.setContent(`<main><button>Only button</button></main>`)
  const single = await createSnapshotHelpers(page, registry()).snapshot({ within: "main" })
  assert.equal(single.split("\n")[0]?.startsWith("- "), true, single)
  assert.match(single, /button "Only button"/)
  assert.doesNotMatch(single, /within "main"/)

  // Auto-scoping to a single <main> says what it left outside: a nav of controls is one landmark with two controls.
  const scopedPage = `
    <nav aria-label="Thread list">
      <div role="button" tabindex="0">Thread one</div>
      <div role="button" tabindex="0">Thread two</div>
    </nav>
    <main><p>x</p><button>Send message</button></main>
  `
  const scopedNote = 'scoped to <main>; 1 landmark and 2 controls outside it are not shown (within: "body" to include them)'
  await page.setContent(scopedPage)
  const scoped = await createSnapshotHelpers(page, registry()).snapshot()
  assert.equal(scoped.split("\n")[0], scopedNote, scoped)
  assert.match(scoped, /button "Send message"/)
  assert.doesNotMatch(scoped, /Thread one/)

  // Nothing interactive outside main: there is nothing to report.
  await page.setContent(`<main><p>x</p><button>Send message</button></main>`)
  const nothingOutside = await createSnapshotHelpers(page, registry()).snapshot()
  assert.doesNotMatch(nothingOutside, /scoped to <main>/, nothingOutside)
  assert.match(nothingOutside, /button "Send message"/)

  // A lone control outside main has no landmark: only the control is worth mentioning, in the singular.
  await page.setContent(`<main><p>x</p></main><div role="button" tabindex="0">Loose action</div>`)
  const loneControl = await createSnapshotHelpers(page, registry()).snapshot()
  assert.equal(
    loneControl.split("\n")[0],
    'scoped to <main>; 1 control outside it is not shown (within: "body" to include them)',
    loneControl,
  )

  // An explicit within disables auto main scoping, so the whole page, nav rows included, is captured.
  await page.setContent(scopedPage)
  const wholePage = await createSnapshotHelpers(page, registry()).snapshot({ within: "body" })
  assert.match(wholePage, /button "Thread one"/, wholePage)
  assert.match(wholePage, /button "Thread two"/, wholePage)
  assert.doesNotMatch(wholePage, /scoped to <main>/, wholePage)

  // Header controls outside main are re-admitted already, so they are neither omitted nor a landmark.
  await page.setContent(`
    <header><button>Open menu</button></header>
    <main><p>x</p><button>Send message</button></main>
  `)
  const headerReached = await createSnapshotHelpers(page, registry()).snapshot()
  assert.match(headerReached, /button "Open menu"/, headerReached)
  assert.doesNotMatch(headerReached, /scoped to <main>/, headerReached)

  // Controls in main's own shadow DOM are inside main, even though contains() cannot see them.
  await page.setContent(`<main><p>x</p><my-panel></my-panel></main>`)
  await page.evaluate(() => {
    const shadow = document.querySelector("my-panel")!.attachShadow({ mode: "open" })
    shadow.innerHTML = "<button>Shadow one</button><button>Shadow two</button>"
  })
  const shadowed = await createSnapshotHelpers(page, registry()).snapshot()
  assert.doesNotMatch(shadowed, /scoped to <main>/, shadowed)
  assert.match(shadowed, /button "Shadow one"/, shadowed)
  assert.match(shadowed, /button "Shadow two"/, shadowed)

  // An invisible control outside main is not shown, so it is not worth reporting either.
  await page.setContent(`<main><p>x</p><button>Send message</button></main><button style="display:none">Hidden action</button>`)
  const hiddenOutside = await createSnapshotHelpers(page, registry()).snapshot()
  assert.doesNotMatch(hiddenOutside, /scoped to <main>/, hiddenOutside)

  // A landmark wrapping main is the page itself, not something outside main.
  await page.setContent(`<div role="region" aria-label="App"><button>Wrap action</button><main><p>x</p></main></div>`)
  const wrappedMain = await createSnapshotHelpers(page, registry()).snapshot()
  assert.equal(
    wrappedMain.split("\n")[0],
    'scoped to <main>; 1 control outside it is not shown (within: "body" to include them)',
    wrappedMain,
  )
  assert.doesNotMatch(wrappedMain, /landmark/, wrappedMain)

  // A skip link to main is navigation back into the scope, not content outside it.
  await page.setContent(`<a href="#main">Skip to content</a><main id="main"><p>x</p><button>Send message</button></main>`)
  const skipLink = await createSnapshotHelpers(page, registry()).snapshot()
  assert.doesNotMatch(skipLink, /scoped to <main>/, skipLink)

  // A skip link to a wrapper that contains main is still a jump back into the scope.
  await page.setContent(`<div id="content"><a href="#content">Skip to content</a><main><p>x</p><button>Send message</button></main></div>`)
  const skipWrapper = await createSnapshotHelpers(page, registry()).snapshot()
  assert.doesNotMatch(skipWrapper, /scoped to <main>/, skipWrapper)

  // 200 controls is the complete count; only a 201st countable control makes it "200+".
  const outsideControls = (count: number): string => `
    <main><p>x</p><button>Send message</button></main>
    <div>${Array.from({ length: count }, (_, index) => `<div role="button" tabindex="0">Action ${index}</div>`).join("")}</div>
  `
  await page.setContent(outsideControls(200))
  const exactly200 = await createSnapshotHelpers(page, registry()).snapshot()
  assert.equal(
    exactly200.split("\n")[0],
    'scoped to <main>; 200 controls outside it are not shown (within: "body" to include them)',
    exactly200,
  )
  await page.setContent(outsideControls(201))
  const over200 = await createSnapshotHelpers(page, registry()).snapshot()
  assert.equal(
    over200.split("\n")[0],
    'scoped to <main>; 200+ controls outside it are not shown (within: "body" to include them)',
    over200,
  )

  // A header with a re-admitted button is already partly shown, so it is not counted as a landmark.
  await page.setContent(`
    <header><button>Open menu</button><a href="/help">Help</a></header>
    <main><p>x</p><button>Send message</button></main>
  `)
  const partialHeader = await createSnapshotHelpers(page, registry()).snapshot()
  assert.equal(
    partialHeader.split("\n")[0],
    'scoped to <main>; 1 control outside it is not shown (within: "body" to include them)',
    partialHeader,
  )
  assert.doesNotMatch(partialHeader, /landmark/, partialHeader)

  // find narrows the entries, never the notes; a miss still says what was scoped out.
  await page.setContent(scopedPage)
  const noMatch = await createSnapshotHelpers(page, registry()).snapshot({ find: "nothing on this page" })
  assert.equal(noMatch, `${scopedNote}\nNo snapshot lines matched "nothing on this page".`, noMatch)

  // A ref root stays strict: the forgiving fallback is only for a `within` selector string.
  const refButton = async (): Promise<{ helpers: ReturnType<typeof createSnapshotHelpers>; refId: string }> => {
    await page.setContent(`<main><button id="dup">Duplicate me</button></main>`)
    const helpers = createSnapshotHelpers(page, registry())
    const refId = /button "Duplicate me" \[ref=(e\d+)\]/.exec(await helpers.snapshot())?.[1]
    assert.ok(refId, "expected a ref for the duplicate button")
    return { helpers, refId }
  }
  const duplicated = await refButton()
  await page.evaluate(() => { document.body.appendChild(document.querySelector("#dup")!.cloneNode(true)) })
  await assert.rejects(
    duplicated.helpers.snapshot({ within: duplicated.helpers.ref(duplicated.refId) }),
    /snapshot within expects exactly one match for selector: #dup; got 2/,
  )
  const dropped = await refButton()
  await page.evaluate(() => document.querySelector("#dup")!.remove())
  await assert.rejects(
    dropped.helpers.snapshot({ within: dropped.helpers.ref(dropped.refId) }),
    /snapshot within expects exactly one match for selector: #dup; got 0/,
  )

  // Readonly text fields show the value the page generated; editable, password, one-time-code and card values stay hidden.
  const readonlyContent = `
    <main>
      <input type="text" readonly value="someone@example.com">
      <input type="password" readonly value="hunter2">
      <input type="text" readonly autocomplete="one-time-code" value="424242">
      <input type="text" readonly autocomplete="cc-number" value="4111111111111111">
      <input type="text" value="private-marker">
      <input type="text" disabled>
      <textarea readonly>readonly-notes</textarea>
      <textarea>editable-notes</textarea>
      <input type="checkbox" readonly value="cbval">
      <input type="submit" readonly value="SubmitVal">
      <input type="checkbox" disabled>
    </main>
  `
  await page.setContent(readonlyContent)
  const readonlySnapshot = await createSnapshotHelpers(page, registry()).snapshot()
  assert.match(readonlySnapshot, /readonly value="someone@example\.com"/, readonlySnapshot)
  assert.match(readonlySnapshot, /readonly value="readonly-notes"/, readonlySnapshot)
  assert.equal((readonlySnapshot.match(/^- textbox "textbox"/gm) ?? []).length, 8, readonlySnapshot)
  assert.match(readonlySnapshot, /textbox "textbox" \[ref=e\d+ disabled\]/, readonlySnapshot)
  assert.doesNotMatch(readonlySnapshot, /hunter2|424242|4111111111111111|private-marker|editable-notes/)
  assert.doesNotMatch(readonlySnapshot, /readonly value="(?:cbval|SubmitVal)"/, readonlySnapshot)
  assert.doesNotMatch(readonlySnapshot, /^- checkbox "checkbox" .*disabled/m, readonlySnapshot)

  // A fresh CDP context: the redaction selector has to be registered before the page's first evaluate.
  const readonlyConnection = await chromium.connectOverCDP(`http://127.0.0.1:${cdpPort}`)
  try {
    const readonlyPage = await readonlyConnection.contexts()[0]!.newPage()
    await readonlyPage.setContent(readonlyContent)
    const readonlyAria = await createAriaSnapshotHelper(readonlyPage)("main")
    assert.match(readonlyAria, /someone@example\.com/, readonlyAria)
    assert.match(readonlyAria, /readonly-notes/, readonlyAria)
    assert.doesNotMatch(readonlyAria, /hunter2|424242|4111111111111111|private-marker|editable-notes/)
    await readonlyPage.close()
  } finally { await readonlyConnection.close() }

  // --- iframes ---
  await page.goto(`http://127.0.0.1:${hostPort}/`)
  for (const title of ["payment", "same"]) {
    await page.frameLocator(`iframe[title="${title}"]`).locator("h1").waitFor()
  }
  await page.frameLocator('iframe[title="payment"]').frameLocator('iframe[title="nested"]').locator("h1").waitFor()
  const frameHelpers = createSnapshotHelpers(page, registry())
  const frameSnapshot = await frameHelpers.snapshot()
  const printed = frameSnapshot.split("\n")
  const indentOf = (line: string) => line.length - line.trimStart().length
  const dialogIndex = printed.findIndex((line) => line.includes('- dialog "Pagar"'))
  const paymentIndex = printed.findIndex((line) => line.includes('- iframe "payment"'))
  const sameIndex = printed.findIndex((line) => line.includes('- iframe "same"'))
  assert.ok(dialogIndex >= 0 && paymentIndex >= 0, frameSnapshot)
  assert.ok(sameIndex > paymentIndex, frameSnapshot)
  // The dialog is the capture root and its own entry; both iframes sit one level under it.
  assert.equal(indentOf(printed[paymentIndex]!), indentOf(printed[dialogIndex]!) + 2, frameSnapshot)
  assert.equal(indentOf(printed[sameIndex]!), indentOf(printed[dialogIndex]!) + 2, frameSnapshot)
  assert.match(frameSnapshot, /- iframe "payment" \[ref=e\d+ src=localhost:\d+\]/, frameSnapshot)
  assert.match(frameSnapshot, /- iframe "same" \[ref=e\d+ src=127\.0\.0\.1:\d+\]/, frameSnapshot)
  // Both documents are captured, nested under their iframe line, and cross-origin content is included.
  const inFrame = (index: number, pattern: RegExp) => {
    const base = indentOf(printed[index]!)
    for (let cursor = index + 1; cursor < printed.length; cursor++) {
      const line = printed[cursor]!
      if (line.startsWith("- ") || indentOf(line) <= base) return false
      if (pattern.test(line)) return true
    }
    return false
  }
  assert.ok(inFrame(paymentIndex, /heading "Pay form"/), frameSnapshot)
  assert.ok(inFrame(sameIndex, /heading "Same form"/), frameSnapshot)
  assert.equal((frameSnapshot.match(/textbox "Card number"/g) ?? []).length, 3, "cross-origin, same-origin and nested frames each print a card field")

  // Frames are cheaper to leave out when they are irrelevant: the iframe line stays, its content does not.
  const withoutFrames = await createSnapshotHelpers(page, registry()).snapshot({ frames: false })
  assert.match(withoutFrames, /- iframe "payment"/)
  assert.doesNotMatch(withoutFrames, /Pay form/)

  // A ref from the cross-origin document clicks inside that document.
  const crossOriginButton = refFor(frameSnapshot, "button", "Pagar", '- iframe "payment"')
  const sameOriginField = refFor(frameSnapshot, "textbox", "Card number", '- iframe "same"')
  assert.ok(crossOriginButton, frameSnapshot)
  assert.ok(sameOriginField, frameSnapshot)
  await frameHelpers.ref(crossOriginButton).click()
  assert.equal(await page.frameLocator('iframe[title="payment"]').locator("button").textContent(), "Paid")
  await frameHelpers.ref(sameOriginField).fill("4242 4242 4242 4242")
  assert.equal(await page.frameLocator('iframe[title="same"]').locator("input[name=card]").inputValue(), "4242 4242 4242 4242")

  // find still sees frame content.
  const found = await frameHelpers.snapshot({ find: "Expiry" })
  assert.match(found, /matching snapshot lines/)
  assert.match(found, /textbox "Expiry"/)

  // A `within` locator in a frame captures there and its refs resolve there.
  const withinFrame = createSnapshotHelpers(page, registry())
  const frameBody = page.frameLocator('iframe[title="payment"]').locator("body")
  const withinOutput = await withinFrame.snapshot({ within: frameBody })
  assert.match(withinOutput, /heading "Pay form"/)
  assert.doesNotMatch(withinOutput, /Checkout/)
  const withinRef = refFor(withinOutput, "textbox", "Expiry")
  assert.ok(withinRef, withinOutput)
  assert.equal(await withinFrame.ref(withinRef).count(), 1)
  await withinFrame.ref(withinRef).fill("12/34")
  assert.equal(await page.frameLocator('iframe[title="payment"]').locator("input[name=expiry]").inputValue(), "12/34")

  // `within: ref("eN")` captures in the frame the ref came from.
  const beforeFrameRoot = await frameHelpers.snapshot()
  const frameControl = refFor(beforeFrameRoot, "textbox", "Expiry", '- iframe "payment"')
  assert.ok(frameControl, beforeFrameRoot)
  const withinFrameRef = await frameHelpers.snapshot({ within: frameHelpers.ref(frameControl) })
  assert.match(withinFrameRef, /textbox "Expiry"/)
  assert.doesNotMatch(withinFrameRef, /Checkout/)

  // A frame ref fails closed once that frame navigates.
  const beforeNavigation = await frameHelpers.snapshot()
  const paymentControl = refFor(beforeNavigation, "textbox", "Expiry", '- iframe "payment"')
  assert.ok(paymentControl, beforeNavigation)
  const crossOriginFrame = page.frames().find((frame) => frame.url().includes("localhost"))
  assert.ok(crossOriginFrame, "cross-origin frame is a real Playwright frame")
  await crossOriginFrame.goto(`http://localhost:${crossOriginPort}/moved`)
  await page.frameLocator('iframe[title="payment"]').locator("h1").filter({ hasText: "Moved" }).waitFor()
  assert.throws(
    () => frameHelpers.ref(paymentControl),
    /was captured in an iframe that has navigated or detached; call snapshot\(\) again/,
  )

  // ariaSnapshot includes iframe content but never values typed into one, cross-origin or same-origin.
  await page.goto(`http://127.0.0.1:${hostPort}/`)
  for (const title of ["payment", "same"]) {
    await page.frameLocator(`iframe[title="${title}"]`).locator("h1").waitFor()
  }
  const ariaHelpers = createAriaSnapshotHelper(page)
  await page.frameLocator('iframe[title="payment"]').locator("input[name=card]").fill("cross-secret")
  await page.frameLocator('iframe[title="same"]').locator("input[name=card]").fill("same-secret")
  await page.frameLocator('iframe[title="payment"]').frameLocator('iframe[title="nested"]').locator("input[name=card]").fill("nested-secret")
  const aria = await ariaHelpers()
  assert.match(aria, /^- iframe "payment" \[src=localhost:\d+\]:$/m, aria)
  assert.match(aria, /^- iframe "same" \[src=127\.0\.0\.1:\d+\]:$/m, aria)
  assert.match(aria, /^  - iframe "nested" \[src=127\.0\.0\.1:\d+\]:$/m, aria)
  assert.match(aria, /heading "Pay form"/, aria)
  assert.match(aria, /heading "Same form"/, aria)
  assert.match(aria, /heading "Nested"/, aria)
  assert.doesNotMatch(aria, /cross-secret/)
  assert.doesNotMatch(aria, /same-secret/)
  assert.doesNotMatch(aria, /nested-secret/)
  assert.doesNotMatch(aria, /\[ref=|\[active\]|\bgeneric\b/, "the default format is kept")
  // A target inside the frame redacts that frame and the frames nested under it too.
  const ariaInFrame = await ariaHelpers(page.frameLocator('iframe[title="payment"]').locator("body"))
  assert.match(ariaInFrame, /heading "Pay form"/)
  assert.match(ariaInFrame, /^- iframe "nested" \[src=127\.0\.0\.1:\d+\]:\n  - heading "Nested"/m, ariaInFrame)
  assert.doesNotMatch(ariaInFrame, /cross-secret/)
  assert.doesNotMatch(ariaInFrame, /nested-secret/)
  // Values are in the DOM; only the snapshot redacts them.
  assert.equal(await page.frameLocator('iframe[title="payment"]').locator("input[name=card]").inputValue(), "cross-secret")

  // diff reports a change made inside a frame, against a baseline taken with the same options.
  await page.goto(`http://127.0.0.1:${hostPort}/`)
  await page.frameLocator('iframe[title="payment"]').locator("h1").waitFor()
  const diffHelpers = createSnapshotHelpers(page, registry())
  const baseline = await diffHelpers.snapshot()
  const diffButton = refFor(baseline, "button", "Pagar", '- iframe "payment"')
  assert.ok(diffButton, baseline)
  await diffHelpers.ref(diffButton).click()
  const diff = await diffHelpers.snapshot({ diff: true })
  assert.match(diff, /\+\s+button "Paid"/, diff)

  // The frame budget is honest about the iframes it leaves out.
  await page.goto(`http://127.0.0.1:${hostPort}/many`)
  await page.frameLocator('iframe[title="same-0"]').locator("h1").waitFor()
  const many = await createSnapshotHelpers(page, registry()).snapshot({ maxItems: 200 })
  assert.match(many, /- \.\.\. 2 iframe contents not captured \(8 iframes at most per snapshot\)/, many)
  assert.match(many, /- iframe "same-9"/, many)

  // D: a modal without iframes keeps dev's shape: dialog at 0, heading at 1, its controls at 2.
  await page.goto(`http://127.0.0.1:${hostPort}/modal`)
  const modalSnapshot = await createSnapshotHelpers(page, registry()).snapshot()
  const modalLines = modalSnapshot.split("\n")
  const modalLine = (needle: string) => modalLines.findIndex((line) => line.includes(needle))
  assert.ok(modalLine('- dialog "Modal"') >= 0, modalSnapshot)
  assert.equal(indentOf(modalLines[modalLine('- dialog "Modal"')]!), 0, modalSnapshot)
  assert.equal(indentOf(modalLines[modalLine('heading "Details"')]!), 2, modalSnapshot)
  assert.equal(indentOf(modalLines[modalLine('textbox "Email"')]!), 4, modalSnapshot)
  assert.equal(indentOf(modalLines[modalLine('button "Apply"')]!), 4, modalSnapshot)
  assert.doesNotMatch(modalSnapshot, /iframe "tiny"/, "a 10x10 iframe is not worth a line")

  // E: ad iframes have ordinary priority; with a small maxItems the real control still makes it in.
  await page.goto(`http://127.0.0.1:${hostPort}/ads`)
  await page.frameLocator('iframe[title="ad-0"]').locator("h1").waitFor()
  const crowded = await createSnapshotHelpers(page, registry()).snapshot({ maxItems: 4, frames: false })
  assert.match(crowded, /button "Real action"/, crowded)
  assert.ok((crowded.match(/- iframe/g) ?? []).length < 6, crowded)

  // B: removing the first iframe never retargets its refs to the frame that shifts up.
  await page.goto(`http://127.0.0.1:${hostPort}/`)
  for (const title of ["payment", "same"]) {
    await page.frameLocator(`iframe[title="${title}"]`).locator("h1").waitFor()
  }
  const identityHelpers = createSnapshotHelpers(page, registry())
  const identityBefore = await identityHelpers.snapshot()
  const paymentButton = refFor(identityBefore, "button", "Pagar", '- iframe "payment"')
  const sameButton = refFor(identityBefore, "button", "Pagar", '- iframe "same"')
  assert.ok(paymentButton && sameButton, identityBefore)
  await page.evaluate(() => document.querySelector('iframe[title="payment"]')!.remove())
  const identityAfter = await identityHelpers.snapshot()
  assert.throws(() => identityHelpers.ref(paymentButton!), /Unknown snapshot ref/, identityAfter)
  assert.equal(refFor(identityAfter, "button", "Pagar", '- iframe "same"'), sameButton, identityAfter)

  // F: a bare FrameLocator scopes the snapshot to that frame's document.
  const frameScopeHelpers = createSnapshotHelpers(page, registry())
  const bareScope = await frameScopeHelpers.snapshot({ within: page.frameLocator('iframe[title="same"]') })
  assert.match(bareScope, /heading "Same form"/, bareScope)
  const bareRef = refFor(bareScope, "textbox", "Card number")
  assert.ok(bareRef, bareScope)
  assert.equal(await frameScopeHelpers.ref(bareRef).count(), 1)

  // I: a `within` ref root rechecks its frame; a ref resolved before the navigation cannot be used after it.
  await page.goto(`http://127.0.0.1:${hostPort}/`)
  await page.frameLocator('iframe[title="payment"]').locator("h1").waitFor()
  const staleHelpers = createSnapshotHelpers(page, registry())
  const staleSnapshot = await staleHelpers.snapshot()
  const staleControl = refFor(staleSnapshot, "textbox", "Card number", '- iframe "payment"')
  assert.ok(staleControl, staleSnapshot)
  const staleRoot = staleHelpers.ref(staleControl)
  const staleFrame = page.frames().find((frame) => frame.url().includes("localhost"))
  assert.ok(staleFrame, "cross-origin frame is a real Playwright frame")
  await staleFrame.goto(`http://localhost:${crossOriginPort}/moved`)
  await assert.rejects(
    () => staleHelpers.snapshot({ within: staleRoot }),
    /stale after an iframe navigation or detach/,
  )

  // An aria-hidden host in a shadow root and a 0x0 iframe make line-to-element mapping impossible; the tree is
  // left alone and each captured frame gets a label that names the frame it actually is.
  await page.goto(`http://127.0.0.1:${hostPort}/mislabel`)
  await page.frameLocator('iframe[title="hidden-host"]').locator("h1").waitFor()
  const mislabel = await createAriaSnapshotHelper(page)()
  assert.match(mislabel, /^\s+- iframe$/m, mislabel)
  assert.match(mislabel, /- iframe "hidden-host" \[src=127\.0\.0\.1:\d+\]:\n  - heading "B frame"/, mislabel)
  assert.doesNotMatch(mislabel, /- iframe "zero"/, "a 0x0 iframe is not captured")
  assert.doesNotMatch(mislabel, /heading "A frame"/)

  // --- ariaSnapshot: frames are read one document at a time, each with its own redaction ---
  await page.goto(`http://127.0.0.1:${hostPort}/`)
  await page.frameLocator('iframe[title="payment"]').locator("h1").waitFor()
  const leakHelpers = createAriaSnapshotHelper(page)
  // An iframe inserted just before the snapshot is read through its own token, redacted in its own frame.
  await page.evaluate((url) => {
    const iframe = document.createElement("iframe")
    iframe.src = url
    iframe.title = "late"
    document.body.appendChild(iframe)
  }, `http://127.0.0.1:${hostPort}/frame-leak`)
  await page.frameLocator('iframe[title="late"]').locator("h1").waitFor()
  const inserted = await leakHelpers()
  assert.match(inserted, /heading "Late"/, inserted)
  assert.doesNotMatch(inserted, /LEAK-VALUE-ATTR/)

  // A cross-origin frame navigated just before, or while, the snapshot runs never returns the new values.
  const crossOrigin = page.frames().find((frame) => frame.url().includes("localhost"))
  assert.ok(crossOrigin, "cross-origin frame is a real Playwright frame")
  await crossOrigin.goto(`http://localhost:${crossOriginPort}/leak`)
  const navigated = await leakHelpers()
  assert.doesNotMatch(navigated, /LEAK-VALUE-CROSS/)
  const pendingAria = leakHelpers()
  await pause(5)
  await crossOrigin.goto(`http://localhost:${crossOriginPort}/leak?again`).catch(() => {})
  assert.doesNotMatch(await pendingAria, /LEAK-VALUE-CROSS/)

  // A frame whose redaction cannot be activated becomes a note, is not left patched, and does not fail the rest.
  const brokenConnection = await chromium.connectOverCDP(`http://127.0.0.1:${cdpPort}`)
  try {
    const brokenPage = await brokenConnection.contexts()[0]!.newPage()
    await brokenPage.goto(`http://127.0.0.1:${hostPort}/redact-fail`)
    const brokenFrame = brokenPage.frames().find((frame) => frame.url().includes("/frame-leak"))
    assert.ok(brokenFrame, "the broken frame loaded")
    // Warm only that frame's utility world, before the redaction engine is registered for this context.
    await brokenFrame.locator("body").innerText()
    const brokenAria = await createAriaSnapshotHelper(brokenPage)()
    assert.match(brokenAria, /heading "Host"/, brokenAria)
    assert.match(brokenAria, /content not captured/, brokenAria)
    assert.match(brokenAria, /heading "Working"/, "a healthy frame still gets its content")
    assert.doesNotMatch(brokenAria, /LEAK-VALUE-ATTR/)
    assert.equal(
      await brokenPage.frameLocator('iframe[title="broken"]').locator("input").inputValue(),
      "LEAK-VALUE-ATTR",
      "a frame whose activation failed is not left patched",
    )
    await brokenPage.close()
  } finally { await brokenConnection.close() }

  // One slow frame (1.5s) gets the caller's time when it is the only frame, rather than an eighth of it.
  await page.goto(`http://127.0.0.1:${hostPort}/slow-parent`, { waitUntil: "domcontentloaded" })
  const slowSnapshot = await createSnapshotHelpers(page, registry()).snapshot({ timeout: 5_000 })
  assert.match(slowSnapshot, /- iframe "slow"[\s\S]*heading "Slow"/, slowSnapshot)
  const slowAria = await createAriaSnapshotHelper(page)()
  assert.match(slowAria, /- iframe "slow" \[src=localhost:\d+\]:\n  - heading "Slow"/, slowAria)

  // Tiny iframes are filtered before the 8-frame cap, so they are not counted in the skip note either.
  await page.goto(`http://127.0.0.1:${hostPort}/aria-many`)
  await page.frameLocator('iframe[title="many-0"]').locator("h1").waitFor()
  const ariaMany = await createAriaSnapshotHelper(page)()
  assert.match(ariaMany, /- \.\.\. 2 iframe contents not captured \(8 iframes at most per snapshot\)/, ariaMany)
  assert.doesNotMatch(ariaMany, /iframe "tiny-/)

  // A hung frame nested inside the first iframe is bounded by that frame's slice, so the next sibling is still
  // captured instead of inheriting the whole snapshot deadline.
  await page.goto(`http://127.0.0.1:${hostPort}/nested-hung`, { waitUntil: "domcontentloaded" })
  await page.frameLocator('iframe[title="b"]').locator("h1").waitFor()
  const nestedSnapshot = await createSnapshotHelpers(page, registry()).snapshot({ timeout: 5_000 })
  assert.match(nestedSnapshot, /content not captured \(the frame did not answer in time\)/, nestedSnapshot)
  assert.match(nestedSnapshot, /- iframe "b"[\s\S]*heading "Working"/, nestedSnapshot)
  const nestedAria = await createAriaSnapshotHelper(page)(undefined, { timeout: 5_000 })
  assert.match(nestedAria, /- iframe "b" \[src=127\.0\.0\.1:\d+\]:\n  - heading "Working"/, nestedAria)
  await page.goto("about:blank")

  // A page without iframes keeps dev's output even when its tree read runs past the caller's timeout: the cheap
  // listing still runs, finds nothing, and must not add an iframe deadline note.
  await page.goto(`http://127.0.0.1:${hostPort}/late-target`)
  const lateTarget = await createAriaSnapshotHelper(page)("#late", { timeout: 2_000 })
  assert.match(lateTarget, /heading "Late"/, lateTarget)
  assert.doesNotMatch(lateTarget, /iframe contents not captured/, lateTarget)

  // One hung frame gets a capped timeout, so a healthy frame after it is still captured (snapshot and aria).
  await page.goto(`http://127.0.0.1:${hostPort}/hung-parent`, { waitUntil: "domcontentloaded" })
  await page.frameLocator('iframe[title="healthy"]').locator("h1").waitFor()
  const hungSnapshot = await createSnapshotHelpers(page, registry()).snapshot({ timeout: 5_000 })
  assert.match(hungSnapshot, /- iframe "hung"/, hungSnapshot)
  assert.match(hungSnapshot, /content not captured \(the frame did not answer in time\)/, hungSnapshot)
  assert.match(hungSnapshot, /- iframe "healthy"[\s\S]*heading "Working"/, hungSnapshot)
  const hungAria = await createAriaSnapshotHelper(page)()
  assert.match(hungAria, /- iframe "hung" \[src=localhost:\d+\]:\n  - \.\.\. content not captured/, hungAria)
  assert.match(hungAria, /- iframe "healthy" \[src=127\.0\.0\.1:\d+\]:\n  - heading "Working"/, hungAria)
  await page.goto("about:blank")

  console.log(JSON.stringify({
    multiple: "PASS",
    hidden: "PASS",
    missing: "PASS",
    single: "PASS",
    mainScopeNote: "PASS",
    noMainScopeNote: "PASS",
    loneControlNote: "PASS",
    withinBodyScope: "PASS",
    headerReached: "PASS",
    shadowMainScope: "PASS",
    hiddenOutside: "PASS",
    wrappedMainLandmark: "PASS",
    skipLinkScope: "PASS",
    skipWrapperScope: "PASS",
    exactly200: "PASS",
    over200: "PASS",
    partialHeader: "PASS",
    findNoMatchNote: "PASS",
    refStrict: "PASS",
    readonlyValues: "PASS",
    frames: "PASS",
    crossOriginRef: "PASS",
    withinFrame: "PASS",
    frameRefClosed: "PASS",
    ariaFrames: "PASS",
    frameBudget: "PASS",
    modalDepth: "PASS",
    framePriority: "PASS",
    frameIdentity: "PASS",
    frameScope: "PASS",
    ariaLabelledBlocks: "PASS",
    withinRefRecheck: "PASS",
    ariaNoLeak: "PASS",
    ariaRedactionFailure: "PASS",
    hungFrame: "PASS",
    lateTreeNoIframeNote: "PASS",
    singleSlowFrame: "PASS",
    nestedHungSibling: "PASS",
    ariaTinyNotCounted: "PASS",
  }))
} finally {
  await browser.close().catch(() => {})
  await new Promise<void>((resolve) => hostServer.close(() => resolve()))
  await new Promise<void>((resolve) => crossOriginServer.close(() => resolve()))
  await new Promise<void>((resolve) => hungServer.close(() => resolve()))
}

import { Data } from "effect"
import type { CdpEvent, JsonObject } from "../protocol.ts"
import type { ChildTarget, ConnectedTarget } from "../relay/types.ts"

type ClientCdpSessionAlias = Data.TaggedEnum<{
  Browser: {}
  Target: { readonly tabId: number; readonly targetId: string; readonly chromeSessionId?: string }
}>
export const ClientCdpSessionAlias = Data.taggedEnum<ClientCdpSessionAlias>()

type AnnouncedTarget = {
  readonly tabId: number
  readonly targetId: string
  readonly sessionId: string
  readonly parentSessionId?: string
}

type CdpClientState = {
  readonly aliases: Map<string, ClientCdpSessionAlias>
  readonly announcements: Map<string, AnnouncedTarget>
  readonly opencodeBrowserSessionId?: string
  readonly kind: "raw" | "sandbox"
  autoAttachParams?: JsonObject
}

export class CdpClientPool<Client extends object> implements Iterable<Client> {
  private readonly states = new Map<Client, CdpClientState>()
  /** Per tab, the clients that enabled Fetch on its root or a child session, keyed by routed session. */
  private readonly interceptionOwners = new Map<number, Map<string | undefined, Set<Client>>>()
  private nextAliasId = 1
  private connectionGeneration = 0

  constructor(
    private readonly send: (client: Client, event: CdpEvent) => void,
    /** Observe every canonical session this client stops seeing, announced or silent. */
    private readonly retired: (client: Client, sessionId: string) => void,
    /** A tab's last Fetch-interception owner went away and no client can answer its paused requests any more. */
    private readonly onInterceptionEmpty: (tabId: number) => void = () => {},
  ) {}

  register(client: Client, opencodeBrowserSessionId?: string, kind: "raw" | "sandbox" = "raw"): void {
    if (this.states.has(client)) throw new Error("CDP client is already registered")
    this.states.set(client, {
      aliases: new Map(),
      announcements: new Map(),
      kind: opencodeBrowserSessionId ? kind : "raw",
      ...(opencodeBrowserSessionId ? { opencodeBrowserSessionId } : {}),
    })
    this.connectionGeneration += 1
  }

  unregister(client: Client): number | undefined {
    const registered = this.states.delete(client)
    this.dropClientInterceptions(client)
    if (!registered || this.states.size !== 0) return undefined
    return ++this.connectionGeneration
  }

  /** Records a client that enabled Fetch on the tab's root (`sessionId` undefined) or a child session. */
  markInterceptionOwner(client: Client, tabId: number, sessionId?: string): void {
    if (!this.states.has(client)) return
    const sessions = this.interceptionOwners.get(tabId) ?? new Map<string | undefined, Set<Client>>()
    const owners = sessions.get(sessionId) ?? new Set<Client>()
    owners.add(client)
    sessions.set(sessionId, owners)
    this.interceptionOwners.set(tabId, sessions)
  }

  /** Whether a client still owns the tab's Fetch interception on this routed session. */
  hasInterceptionOwner(tabId: number, sessionId?: string): boolean {
    return (this.interceptionOwners.get(tabId)?.get(sessionId)?.size ?? 0) > 0
  }

  /** Whether any client still owns Fetch interception on any session of the tab. */
  hasInterceptionOwners(tabId: number): boolean {
    const sessions = this.interceptionOwners.get(tabId)
    if (!sessions) return false
    for (const owners of sessions.values()) if (owners.size > 0) return true
    return false
  }

  /**
   * Drops a client's ownership of one routed session after it forwarded Fetch.disable. `releaseTab` is false there:
   * the disable itself is the release, and a tab-wide release would send it again for the session.
   */
  clearInterceptionOwner(client: Client, tabId: number, sessionId: string | undefined, releaseTab = true): void {
    const sessions = this.interceptionOwners.get(tabId)
    const owners = sessions?.get(sessionId)
    if (!sessions || !owners?.delete(client)) return
    if (owners.size === 0) sessions.delete(sessionId)
    if (sessions.size > 0) return
    if (releaseTab) this.dropInterceptionTab(tabId)
    else this.interceptionOwners.delete(tabId)
  }

  get size(): number {
    return this.states.size
  }

  has(client: Client): boolean {
    return this.states.has(client)
  }

  [Symbol.iterator](): IterableIterator<Client> {
    return this.states.keys()
  }

  sessionId(client: Client): string | undefined {
    return this.states.get(client)?.opencodeBrowserSessionId
  }

  isSandbox(client: Client): boolean {
    return this.states.get(client)?.kind === "sandbox"
  }

  hasSession(client: Client, sessionId: string): boolean {
    return this.states.get(client)?.announcements.has(sessionId) ?? false
  }

  announce(client: Client, target: ConnectedTarget | ChildTarget): void {
    const state = this.requireState(client)
    const targetId = target.targetInfo.targetId
    const existing = Array.from(state.announcements.values()).find((entry) => entry.targetId === targetId)
    if (existing?.sessionId === target.sessionId) return
    if (existing) this.detachSession(client, state, existing.sessionId)
    this.detachSession(client, state, target.sessionId)
    const parent = "parentSessionId" in target ? { parentSessionId: target.parentSessionId } : {}
    state.announcements.set(target.sessionId, { tabId: target.tabId, targetId, sessionId: target.sessionId, ...parent })
    this.send(client, {
      ...(parent.parentSessionId === undefined ? {} : { sessionId: parent.parentSessionId }),
      method: "Target.attachedToTarget",
      params: {
        sessionId: target.sessionId,
        targetInfo: { ...target.targetInfo, attached: true },
        waitingForDebugger: "waitingForDebugger" in target ? target.waitingForDebugger : false,
      },
    })
  }

  detach(client: Client, sessionId: string): void {
    const state = this.requireState(client)
    if (state.aliases.delete(sessionId)) return
    this.detachSession(client, state, sessionId, { notify: false })
  }

  detachTab(tabId: number, options: { readonly destroyed?: boolean } = {}): void {
    for (const [client, state] of this.states) {
      this.removeTargetAliases(state, (alias) => alias.tabId === tabId)
      for (const announced of state.announcements.values()) {
        if (announced.tabId === tabId) this.detachSession(client, state, announced.sessionId, options)
      }
    }
    this.dropInterceptionTab(tabId)
  }

  detachTarget(target: ChildTarget, options: { readonly notify?: boolean } = {}): void {
    for (const [client, state] of this.states) {
      this.removeTargetAliases(state, (alias) => alias.targetId === target.targetInfo.targetId)
      this.detachSession(client, state, target.sessionId, options)
    }
    this.dropInterceptionSession(target.tabId, target.sessionId)
  }

  pruneInvisible(client: Client, canSeeTab: (tabId: number) => boolean): void {
    const state = this.requireState(client)
    this.removeTargetAliases(state, (alias) => !canSeeTab(alias.tabId))
    for (const announced of state.announcements.values()) {
      if (!canSeeTab(announced.tabId)) this.detachSession(client, state, announced.sessionId)
    }
  }

  sendToViewers(rootSessionId: string, event: CdpEvent, canSeeTab: (client: Client, tabId: number) => boolean): void {
    for (const [client, state] of this.states) {
      const announced = state.announcements.get(rootSessionId)
      if (!announced) continue
      if (!canSeeTab(client, announced.tabId)) {
        this.pruneInvisible(client, (tabId) => canSeeTab(client, tabId))
        continue
      }
      this.send(client, event)
    }
  }

  setAutoAttachParams(client: Client, params: JsonObject | undefined): void {
    const state = this.requireState(client)
    if (params === undefined) delete state.autoAttachParams
    else state.autoAttachParams = params
  }

  autoAttachParams(client: Client): JsonObject | undefined {
    return this.states.get(client)?.autoAttachParams
  }

  isCurrentIdleGeneration(generation: number): boolean {
    return this.states.size === 0 && this.connectionGeneration === generation
  }

  createBrowserAlias(client: Client): string {
    const aliasId = this.nextAlias("browser")
    this.requireState(client).aliases.set(aliasId, ClientCdpSessionAlias.Browser())
    return aliasId
  }

  createTargetAlias(client: Client, target: ConnectedTarget | ChildTarget): string {
    const aliasId = this.nextAlias("session")
    this.requireState(client).aliases.set(aliasId, ClientCdpSessionAlias.Target({
      tabId: target.tabId,
      targetId: target.targetInfo.targetId,
      ...("parentSessionId" in target ? { chromeSessionId: target.sessionId } : {}),
    }))
    return aliasId
  }

  alias(client: Client, aliasId: string): ClientCdpSessionAlias | undefined {
    return this.states.get(client)?.aliases.get(aliasId)
  }

  private detachSession(client: Client, state: CdpClientState, sessionId: string, options: {
    readonly notify?: boolean
    readonly destroyed?: boolean
  } = {}): void {
    const announced = state.announcements.get(sessionId)
    if (!announced) return
    state.announcements.delete(sessionId)
    // Without its root announcement the client no longer gets the tab's events, so it cannot answer its paused
    // requests. Dropping the root drops every session this client owned there; child announcements come and go
    // without affecting ownership, because events are delivered through the root.
    if (announced.parentSessionId === undefined) this.dropClientTabInterception(client, announced.tabId)
    this.removeTargetAliases(state, (alias) => alias.targetId === announced.targetId)
    // Descendants must disappear before their parent, including on replacement.
    for (const child of state.announcements.values()) {
      if (child.parentSessionId === sessionId) this.detachSession(client, state, child.sessionId, options)
    }
    this.retired(client, sessionId)
    if (options.notify === false) return
    if (options.destroyed && announced.parentSessionId === undefined) {
      this.send(client, { method: "Target.targetDestroyed", params: { targetId: announced.targetId } })
    }
    this.send(client, {
      ...(announced.parentSessionId === undefined ? {} : { sessionId: announced.parentSessionId }),
      method: "Target.detachedFromTarget",
      params: { sessionId, targetId: announced.targetId },
    })
  }

  private dropClientTabInterception(client: Client, tabId: number): void {
    const sessions = this.interceptionOwners.get(tabId)
    if (!sessions) return
    for (const [sessionId, owners] of sessions) {
      owners.delete(client)
      if (owners.size === 0) sessions.delete(sessionId)
    }
    if (sessions.size === 0) this.dropInterceptionTab(tabId)
  }

  private dropClientInterceptions(client: Client): void {
    for (const tabId of Array.from(this.interceptionOwners.keys())) this.dropClientTabInterception(client, tabId)
  }

  private dropInterceptionSession(tabId: number, sessionId: string): void {
    const sessions = this.interceptionOwners.get(tabId)
    if (!sessions?.delete(sessionId)) return
    if (sessions.size === 0) this.dropInterceptionTab(tabId)
  }

  private dropInterceptionTab(tabId: number): void {
    if (!this.interceptionOwners.delete(tabId)) return
    this.onInterceptionEmpty(tabId)
  }

  private removeTargetAliases(state: CdpClientState, matches: (alias: Data.TaggedEnum.Value<ClientCdpSessionAlias, "Target">) => boolean): void {
    for (const [aliasId, alias] of state.aliases) {
      if (ClientCdpSessionAlias.$is("Target")(alias) && matches(alias)) state.aliases.delete(aliasId)
    }
  }

  private nextAlias(kind: "browser" | "session"): string {
    return `bc-client-${kind}-${this.nextAliasId++}`
  }

  private requireState(client: Client): CdpClientState {
    const state = this.states.get(client)
    if (!state) throw new Error("CDP client is not registered")
    return state
  }
}

import { Effect, Option, Predicate, Schema } from "effect"
import { McpSchema } from "effect/ai"
import type { JsonObject } from "../protocol.ts"
import * as RelayClient from "../relay/client.ts"
import { getObject, getString, parseTargetSelection } from "../relay/helpers.ts"
import {
  ExecuteAftermath,
  ExecuteLogEntry,
  ExecuteLogSummary,
  ExtensionStatus,
  RecordingQuality,
  RelayVersion,
  SessionDeleted,
  SettingsGetResponse,
  SettingsSetResponse,
  type ExecuteResponse,
  type TargetSelection,
} from "../relay/schema.ts"
import { settingKeys, type SettingKey, type SettingValue } from "../relay/user-settings.ts"
import type { UpdateNotice } from "../update.ts"

export type CurrentSession = { id: string; established: boolean }

/**
 * An agent calling the tools: its current session, every session it has made current, whether it shares them with
 * every other unnamed caller, and whether it saw the update note.
 */
export type Caller = CurrentSession & { readonly sessions: Set<string>; readonly shared: boolean; updateNoted: boolean }

export type ExecuteArguments = {
  readonly code: string
  readonly session?: string | undefined
  readonly timeoutMs?: number | undefined
  readonly targetSelection?: TargetSelection
  readonly browser?: string
}

export type AdoptArguments = {
  readonly session?: string | undefined
  readonly targetSelection?: TargetSelection
  readonly tabId?: number
}

/** The one-time note on a tool result: what to tell the user, and that the agent may run the update itself. */
export function mcpUpdateNote(notice: Pick<UpdateNotice, "summary" | "command">): string {
  return `Note: browse has an update: ${notice.summary}. Tell the user they can run \`${notice.command}\` and then restart opencode, or ask you to run it for them.`
}

export function objectSchema(properties: JsonObject, required: readonly string[] = []): JsonObject {
  return {
    type: "object",
    properties,
    required: [...required],
    additionalProperties: false,
  }
}

/**
 * A property accepting exactly `values`, as one single-typed `enum` per JSON type. Settings are the one place a tool
 * schema mixes numbers and strings (`idleMinutes` is 10, 30, 60 or "never"), and some MCP clients reject an `enum`
 * whose values have different types, which fails their whole tool list.
 */
export function valuesSchema(values: readonly SettingValue[], description: string): JsonObject {
  const groups = new Map<string, SettingValue[]>()
  for (const value of values) {
    const type = typeof value === "number" ? (Number.isInteger(value) ? "integer" : "number") : "string"
    groups.set(type, [...(groups.get(type) ?? []), value])
  }
  const variants = [...groups].map(([type, items]) => ({ type, enum: items }))
  return variants.length === 1 ? { ...variants[0]!, description } : { anyOf: variants, description }
}

export const emptyInputSchema = objectSchema({})
export const sessionSchemaProperty = {
  type: "string",
  description: "Optional session id. Defaults to your current session.",
} as const
export const sessionAliasSchemaProperty = { type: "string", description: "Same as id." } as const

/**
 * The execute tool's structured result. The agent's return value appears once (as `value`), and only context that has
 * content is included: no empty warnings, zero-count log summaries or uneventful aftermath.
 */
export const ExecuteToolOutput = Schema.Struct({
  session: Schema.String,
  value: Schema.optionalKey(Schema.Unknown),
  logs: Schema.optionalKey(Schema.Array(ExecuteLogEntry)),
  logSummary: Schema.optionalKey(ExecuteLogSummary),
  warnings: Schema.optionalKey(Schema.Array(Schema.String)),
  diagnostic: Schema.optionalKey(Schema.String),
  aftermath: Schema.optionalKey(ExecuteAftermath),
  notice: Schema.optionalKey(Schema.String),
})

export const StatusToolOutput = Schema.Struct({
  endpoint: Schema.String,
  currentSession: Schema.String,
  sharedSession: Schema.Boolean,
  version: RelayVersion,
  status: ExtensionStatus,
  buildProblem: Schema.optionalKey(Schema.String),
  update: Schema.optionalKey(Schema.Json),
  autoUpdate: Schema.Json,
})

export const CurrentSessionToolOutput = Schema.Struct({
  currentSession: Schema.String,
})

export const SessionDeleteToolOutput = SessionDeleted.pipe(Schema.fieldsAssign({
  currentSession: Schema.String,
}))

/**
 * The result of any `network` action: one object root with the fields the chosen action returns. Action-specific
 * fields are optional so structuredContent validates for every action.
 */
export const NetworkToolOutput = Schema.Struct({
  action: Schema.Literals(["start", "status", "stop", "cancel"]),
  session: Schema.String,
  active: Schema.optionalKey(Schema.Boolean),
  startedAt: Schema.optionalKey(Schema.String),
  entryCount: Schema.optionalKey(Schema.Number),
  responseCount: Schema.optionalKey(Schema.Number),
  failureCount: Schema.optionalKey(Schema.Number),
  capturedBodyBytes: Schema.optionalKey(Schema.Number),
  truncatedBodyCount: Schema.optionalKey(Schema.Number),
  droppedEntryCount: Schema.optionalKey(Schema.Number),
  urlFilter: Schema.optionalKey(Schema.String),
  endsAt: Schema.optionalKey(Schema.String),
  ended: Schema.optionalKey(Schema.String),
  stoppedAt: Schema.optionalKey(Schema.String),
  exchanges: Schema.optionalKey(Schema.Array(Schema.Struct({
    id: Schema.String,
    startedDateTime: Schema.String,
    durationMs: Schema.Number,
    request: Schema.Struct({
      method: Schema.String,
      url: Schema.String,
      headers: Schema.Array(Schema.Struct({ name: Schema.String, value: Schema.String })),
      resourceType: Schema.String,
      body: Schema.optionalKey(Schema.Struct({
        size: Schema.Number,
        mimeType: Schema.String,
        text: Schema.optionalKey(Schema.String),
        truncated: Schema.Boolean,
      })),
      redirectedFrom: Schema.optionalKey(Schema.String),
    }),
    response: Schema.optionalKey(Schema.Struct({
      status: Schema.Number,
      statusText: Schema.String,
      headers: Schema.Array(Schema.Struct({ name: Schema.String, value: Schema.String })),
      body: Schema.optionalKey(Schema.Struct({
        size: Schema.Number,
        mimeType: Schema.String,
        text: Schema.optionalKey(Schema.String),
        truncated: Schema.Boolean,
      })),
    })),
    failure: Schema.optionalKey(Schema.String),
  }))),
  cancelled: Schema.optionalKey(Schema.Boolean),
})

/** The result of any `recording` action, with action-specific fields optional. */
export const RecordingToolOutput = Schema.Struct({
  action: Schema.Literals(["start", "stop", "status", "cancel"]),
  session: Schema.String,
  success: Schema.optionalKey(Schema.Boolean),
  tabId: Schema.optionalKey(Schema.Number),
  startedAt: Schema.optionalKey(Schema.Number),
  path: Schema.optionalKey(Schema.String),
  mimeType: Schema.optionalKey(Schema.String),
  artifactType: Schema.optionalKey(Schema.Literals(["webm", "mp4"])),
  frameRate: Schema.optionalKey(Schema.Number),
  duration: Schema.optionalKey(Schema.Number),
  size: Schema.optionalKey(Schema.Number),
  frameCount: Schema.optionalKey(Schema.Number),
  quality: Schema.optionalKey(RecordingQuality),
  isRecording: Schema.optionalKey(Schema.Boolean),
  error: Schema.optionalKey(Schema.String),
})

/** Settings the MCP tool may read and change. Update behaviour is the user's to set, never an agent's. */
export type AgentSettingKey = Exclude<SettingKey, "autoUpdate">
export const agentSettingKeys: readonly AgentSettingKey[] = settingKeys.filter(
  (key): key is AgentSettingKey => key !== "autoUpdate",
)
const AgentSettingValue = Schema.Union([Schema.String, Schema.Number])
const AgentSettingReport = Schema.Struct({
  value: AgentSettingValue,
  effective: AgentSettingValue,
  allowed: Schema.Array(AgentSettingValue),
  description: Schema.String,
  overriddenBy: Schema.optionalKey(Schema.String),
})
export const AgentSettings = Schema.Record(Schema.Literals(agentSettingKeys), AgentSettingReport)

/** Either the read result or the change result, with a single object root so older MCP clients still see the schema. */
export const SettingsToolOutput = Schema.Struct({
  settings: AgentSettings,
  note: Schema.optionalKey(SettingsGetResponse.fields.note),
  changed: Schema.optionalKey(SettingsSetResponse.fields.changed),
  unchanged: Schema.optionalKey(SettingsSetResponse.fields.unchanged),
  overridden: Schema.optionalKey(SettingsSetResponse.fields.overridden),
  message: Schema.optionalKey(SettingsSetResponse.fields.message),
})

/** The JSON Schema a tool advertises from its Effect Schema (the same conversion Effect's McpServer uses). */
export function toolOutputJson(schema: Schema.Constraint): JsonObject {
  const document = Schema.toJsonSchemaDocument(schema)
  const json = Object.keys(document.definitions).length === 0
    ? document.schema
    : { ...document.schema, $defs: document.definitions }
  return json as unknown as JsonObject
}

function logSummaryHasContent(summary: ExecuteLogSummary | undefined): boolean {
  return summary !== undefined && (
    summary.totalCount > 0 || summary.returnedCount > 0 || summary.repeatedCount > 0 || summary.omittedCount > 0
  )
}

function aftermathHasContent(aftermath: ExecuteAftermath | undefined): boolean {
  return aftermath !== undefined && (
    aftermath.startUrl !== aftermath.endUrl ||
    aftermath.navigations.length > 0 ||
    aftermath.consoleErrorCount > 0 ||
    aftermath.pageErrorCount > 0 ||
    aftermath.handoffs > 0 ||
    aftermath.challenge !== undefined
  )
}

export function executeToolOutput(result: ExecuteResponse & { readonly notice?: string }): typeof ExecuteToolOutput.Type {
  return {
    session: result.session.id,
    ...(result.value === undefined ? {} : { value: result.value }),
    ...(result.logs.length > 0 ? { logs: result.logs } : {}),
    ...(logSummaryHasContent(result.logSummary) ? { logSummary: result.logSummary } : {}),
    ...(result.warnings && result.warnings.length > 0 ? { warnings: result.warnings } : {}),
    ...(result.diagnostic ? { diagnostic: result.diagnostic } : {}),
    ...(aftermathHasContent(result.aftermath) ? { aftermath: result.aftermath } : {}),
    ...(result.notice ? { notice: result.notice } : {}),
  }
}

// Many clients show only the text of an error result, and one cuts error text past 10,000 characters from the middle,
// so an error's text carries its warnings and context and stays under that.
const errorMessageLimit = 3000
const errorLogLimit = 20
const errorLogLineLimit = 300
const errorLogsLimit = 2500

function clip(text: string, limit: number): string {
  if (text.length <= limit) return text
  const head = Math.ceil(limit * 2 / 3)
  const tail = limit - head
  return `${text.slice(0, head)}\n… ${text.length - limit} characters cut …\n${text.slice(-tail)}`
}

function aftermathLine(aftermath: ExecuteAftermath | undefined): string | undefined {
  if (!aftermath) return undefined
  const parts: string[] = []
  if (aftermath.endUrl === null) parts.push("the page closed")
  else if (aftermath.startUrl !== aftermath.endUrl) parts.push(`moved from ${clip(aftermath.startUrl ?? "nowhere", 200)} to ${clip(aftermath.endUrl, 200)}`)
  if (aftermath.navigations.length > 0) parts.push(`${aftermath.navigations.length} navigation${aftermath.navigations.length === 1 ? "" : "s"}`)
  if (aftermath.consoleErrorCount > 0) parts.push(`${aftermath.consoleErrorCount} console error${aftermath.consoleErrorCount === 1 ? "" : "s"}`)
  if (aftermath.pageErrorCount > 0) parts.push(`${aftermath.pageErrorCount} page error${aftermath.pageErrorCount === 1 ? "" : "s"}`)
  if (aftermath.handoffs > 0) parts.push(`${aftermath.handoffs} handoff${aftermath.handoffs === 1 ? "" : "s"}`)
  return parts.length > 0 ? `Page: ${parts.join("; ")}` : undefined
}

function errorLogsBlock(logs: readonly ExecuteLogEntry[]): string | undefined {
  if (logs.length === 0) return undefined
  const lines: string[] = []
  let size = 0
  for (const entry of logs.slice(-errorLogLimit).reverse()) {
    const prefix = entry.source === "page" ? `[page ${entry.type}]` : `[${entry.type}]`
    const repeat = entry.repeatCount && entry.repeatCount > 1 ? ` (×${entry.repeatCount})` : ""
    const line = clip(`${prefix} ${entry.text}${repeat}`, errorLogLineLimit).replaceAll("\n", " ")
    if (size + line.length > errorLogsLimit) break
    lines.unshift(line)
    size += line.length + 1
  }
  const shown = lines.length < logs.length ? `last ${lines.length} of ${logs.length}` : `${logs.length}`
  return `Logs (${shown}):\n${lines.join("\n")}`
}

/** The text of a failed execute: the error first, then the warnings, diagnostic, page movement and recent logs. */
export function executeErrorText(result: ExecuteResponse): string {
  const warnings = result.warnings ?? []
  return [
    clip(result.text, errorMessageLimit),
    warnings.length > 0 ? `Warnings:\n${warnings.map((warning) => `- ${warning}`).join("\n")}` : undefined,
    result.diagnostic ? `Diagnostic: ${result.diagnostic}` : undefined,
    aftermathLine(result.aftermath),
    errorLogsBlock(result.logs),
  ].filter((part): part is string => part !== undefined).join("\n\n")
}

/**
 * The text fallback for an execute. A string return is the agent's own readable text, not JSON; a structured return is
 * its compact JSON value. That keeps one copy of the value outside the structured result.
 */
export function executeToolText(result: ExecuteResponse & { readonly notice?: string }): string {
  const text = result.isError
    ? executeErrorText(result)
    : Predicate.isString(result.value)
      ? result.value
      : result.value === undefined
        ? result.text
        : JSON.stringify(result.value)
  return result.notice ? `${text}\n\n${result.notice}` : text
}

/**
 * The MCP result for one execute: images keep their content blocks and text, errors are text only, and everything else
 * also gets structured output.
 */
export function executeToolResult(value: unknown): McpSchema.CallToolResult {
  const result = value as ExecuteResponse & { readonly notice?: string }
  if (result.media && result.media.length > 0) {
    return new McpSchema.CallToolResult({
      content: [
        McpSchema.TextContent.make({ text: result.isError ? executeErrorText(result) : result.text }),
        ...result.media.map((image) => McpSchema.ImageContent.make({
          data: new Uint8Array(Buffer.from(image.data, "base64")),
          mimeType: image.mimeType,
        })),
      ],
      isError: result.isError,
    })
  }
  // A failed execute is text only: a client that prefers structuredContent would otherwise show the context without
  // the error.
  if (result.isError) return toolResult({ text: executeToolText(result), isError: true })
  return toolResultForValue(executeToolOutput(result), {
    outputSchema: ExecuteToolOutput,
    text: executeToolText(result),
    isError: result.isError,
  })
}

export const ensureSessionExists = Effect.fnUntraced(function* (relay: RelayClient.Interface, id: string) {
  const sessions = yield* relay.sessions
  const exists = sessions.some((session) => {
    return session.id === id
  })
  if (!exists) {
    return yield* Effect.fail(new Error(`Session not found: ${id}`))
  }
})

export function parseExecuteArguments(input: unknown): ExecuteArguments {
  const object = requireObject(input)
  const code = requiredStringField(object, "code")
  const session = optionalStringField(object, "session")
  const timeoutMs = optionalNonNegativeIntegerField(object, "timeoutMs")
  const targetSelection = parseMcpTargetSelection(object)
  const browser = optionalStringField(object, "browser")
  return {
    code,
    ...(session ? { session } : {}),
    ...(timeoutMs === undefined ? {} : { timeoutMs }),
    ...(targetSelection ? { targetSelection } : {}),
    ...(browser ? { browser } : {}),
  }
}

export function parseAdoptArguments(input: unknown): AdoptArguments {
  const object = requireObject(input)
  const session = optionalStringField(object, "session")
  const targetSelection = parseMcpTargetSelection(object)
  const tabId = typeof object.tabId === "number" && Number.isInteger(object.tabId) ? object.tabId : undefined
  if (tabId !== undefined && targetSelection) throw new Error("Use only one of tabId, targetUrl, or targetIndex")
  return {
    ...(session ? { session } : {}),
    ...(targetSelection ? { targetSelection } : {}),
    ...(tabId === undefined ? {} : { tabId }),
  }
}

export function parseMcpTargetSelection(input: JsonObject): TargetSelection | undefined {
  const urlIncludes = optionalStringField(input, "targetUrl")
  const selection = parseTargetSelection({
    ...(urlIncludes ? { urlIncludes } : {}),
    ...(input.targetIndex === undefined ? {} : { index: input.targetIndex }),
  })
  return selection?.urlIncludes || selection?.index !== undefined ? selection : undefined
}

export function requiredStringField(input: unknown, field: string): string {
  const value = optionalStringField(input, field)
  if (!value) {
    throw new Error(`${field} is required`)
  }
  return value
}

/** The `action` of a merged tool, validated against the actions that tool has. */
export function requiredAction<const Action extends string>(input: unknown, actions: readonly Action[]): Action {
  const action = optionalStringField(input, "action")
  if (!action || !(actions as readonly string[]).includes(action)) {
    throw new Error(`action must be one of ${actions.join(", ")}`)
  }
  return action as Action
}

export function optionalStringField(input: unknown, field: string): string | undefined {
  const value = getString(requireObject(input), field)
  return value ? value : undefined
}

export function optionalBooleanField(input: unknown, field: string): boolean | undefined {
  const value = requireObject(input)[field]
  return Predicate.isBoolean(value) ? value : undefined
}

export function optionalPositiveIntegerField(input: unknown, field: string): number | undefined {
  const value = requireObject(input)[field]
  if (value === undefined) return undefined
  if (!Predicate.isNumber(value) || !Number.isInteger(value) || value <= 0) {
    throw new Error(`${field} must be a positive integer`)
  }
  return value
}

export function optionalNonNegativeIntegerField(input: unknown, field: string): number | undefined {
  const value = requireObject(input)[field]
  if (value === undefined) return undefined
  if (!Predicate.isNumber(value) || !Number.isInteger(value) || value < 0) {
    throw new Error(`${field} must be a non-negative integer`)
  }
  return value
}

export function optionalStringArrayField(input: unknown, field: string): readonly string[] | undefined {
  const value = requireObject(input)[field]
  if (value === undefined) return undefined
  if (!Array.isArray(value) || !value.every((item): item is string => Predicate.isString(item) && item.length > 0)) {
    throw new Error(`${field} must be an array of non-empty strings`)
  }
  return value
}

export function requireObject(input: unknown): JsonObject {
  const object = getObject(input)
  if (!object) {
    throw new Error("Expected arguments object")
  }
  return object
}

function stringifyResult(value: unknown): string {
  if (Predicate.isString(value)) {
    return value
  }
  // Compact, not pretty-printed: this text block is only the backwards-compatible fallback for structuredContent.
  return JSON.stringify(value)
}

function encodedStructuredContent(value: unknown, schema: Schema.ConstraintEncoder<unknown, never> | undefined): unknown {
  if (!schema) return value
  const encoded = Schema.encodeUnknownOption(schema)(value)
  return Option.isSome(encoded) ? encoded.value : undefined
}

export type ToolResultOptions = {
  readonly outputSchema?: Schema.ConstraintEncoder<unknown, never>
  readonly text?: string
  readonly isError?: boolean
}

export function toolResultForValue(value: unknown, options: ToolResultOptions = {}): McpSchema.CallToolResult {
  const object = getObject(value)
  const isError = options.isError ?? object?.isError === true
  const media = Array.isArray(object?.media)
    ? object.media.flatMap((item) => {
        const image = getObject(item)
        const mimeType = getString(image, "mimeType")
        const data = getString(image, "data")
        return image?.type === "image" && mimeType !== undefined && data !== undefined
          ? [{ data, mimeType }]
          : []
      })
    : []
  const errorText = isError ? getString(object, "text") : undefined
  if (media.length > 0) {
    const { media: _media, ...rest } = object ?? {}
    const text = options.text ?? errorText ?? stringifyResult(rest)
    // No structuredContent here: some MCP clients send only structuredContent to the model when it is set, dropping the images.
    return new McpSchema.CallToolResult({
      content: [
        McpSchema.TextContent.make({ text }),
        ...media.map((image) =>
          McpSchema.ImageContent.make({
            data: new Uint8Array(Buffer.from(image.data, "base64")),
            mimeType: image.mimeType,
          }),
        ),
      ],
      isError,
    })
  }
  const text = options.text ?? errorText ?? stringifyResult(value)
  const structuredContent = object ? encodedStructuredContent(object, options.outputSchema) : undefined
  return toolResult({
    text,
    ...(structuredContent === undefined ? {} : { structuredContent }),
    isError,
  })
}

export function mcpErrorMessage(tool: string, message: string): string {
  if (!message.startsWith("Session not found:")) {
    return message
  }
  return tool === "execute" || tool === "session_adopt"
    ? `${message} Create it with session_new first, or omit the explicit session id to use the MCP current session.`
    : `${message} Create it with session_new first.`
}

export function toolResult(options: {
  readonly text: string
  readonly structuredContent?: unknown
  readonly isError: boolean
}): McpSchema.CallToolResult {
  return new McpSchema.CallToolResult({
    content: [McpSchema.TextContent.make({ text: options.text })],
    structuredContent: options.structuredContent,
    isError: options.isError,
  })
}

// Writes through the setup log helper once the test has closed this process's stdout pipe, so the write hits EPIPE.
import { log } from "../../src/setup/environment.ts"

setTimeout(() => {
  for (let line = 0; line < 3; line++) log(`setup output ${line}`)
}, 100)

#!/usr/bin/env node
// browse's stable entry, written by install (cli/src/auto-update.ts). opencode's browse MCP server runs this
// file, so its configuration never changes when the runtime updates. Don't edit; install rewrites it.
import { spawn } from "node:child_process"
import { readFileSync } from "node:fs"
import path from "node:path"
import { createInterface } from "node:readline"
import { fileURLToPath, pathToFileURL } from "node:url"

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)))
const runtime = path.join(root, "runtime")
const installed = () => JSON.parse(readFileSync(path.join(runtime, "current.json"), "utf8"))
const current = () => installed().version
const entry = (version) => path.join(runtime, "versions", version, "node_modules", "@opencode", "browse", "dist", "cli.mjs")
process.env.OPENCODE_BROWSER_HOME ??= root
const relayPort = Number(process.env.OPENCODE_BROWSER_PORT) || 19988

const binary = installed().binary
if (binary) {
  // An agent still runs the npm entry after a binary install. The executable supplies its own MCP supervisor.
  const child = spawn(binary, process.argv.slice(2), { stdio: "inherit" })
  for (const signal of ["SIGTERM", "SIGINT"]) process.on(signal, () => child.kill(signal))
  child.on("exit", (code, signal) => { process.exitCode = code ?? (signal ? 1 : 0) })
} else if (process.argv[2] !== "mcp") {
  process.argv[1] = entry(current())
  await import(pathToFileURL(entry(current())).href)
} else {
  const REPLAY = "opencode-browser-shim-initialize"
  // Every server this supervisor starts keeps one implicit session, and the relay watches this process (not the
  // server it replaces), so an update doesn't end the agent's session or close its tabs.
  process.env.OPENCODE_BROWSER_MCP_SESSION ??= "mcp-" + Math.random().toString(16).slice(2, 10).padEnd(8, "0")
  process.env.OPENCODE_BROWSER_CLIENT_PID = String(process.pid)
  let version = current()
  let child
  let initialize
  let initialized
  let swapping = false
  let listChanged = false
  const inflight = new Set()
  const queue = []
  const toClient = (line) => process.stdout.write(line + "\n")
  const toChild = (line) => child.stdin.write(line + "\n")
  const parse = (line) => { try { return JSON.parse(line) } catch { return undefined } }
  // A request is in flight until its response; a cancelled request never gets one, so its client tells us to forget it.
  const trackRequest = (message) => {
    if (!message) return
    if (message.id !== undefined && message.method !== undefined) inflight.add(message.id)
    if (message.method !== "notifications/cancelled" || !message.params || typeof message.params !== "object") return
    const cancelled = message.params.requestId
    if (cancelled !== undefined) inflight.delete(cancelled)
  }
  const forward = (line) => { trackRequest(parse(line)); toChild(line) }

  const start = (replay) => {
    const next = spawn(process.execPath, [entry(version), "mcp"], { stdio: ["pipe", "pipe", "inherit"], env: process.env })
    // A server that exits mid-write (an old one being replaced) must not take the supervisor down with EPIPE.
    next.stdin.on("error", () => {})
    child = next
    next.on("exit", (code, signal) => {
      if (next !== child) return
      process.exit(code ?? (signal ? 1 : 0))
    })
    createInterface({ input: next.stdout }).on("line", (line) => {
      if (next !== child) return
      const message = parse(line)
      if (message && message.id === REPLAY) {
        if (initialized) toChild(initialized)
        swapping = false
        if (listChanged) toClient(JSON.stringify({ jsonrpc: "2.0", method: "notifications/tools/list_changed" }))
        for (const queued of queue.splice(0)) fromClient(queued)
        return
      }
      if (message && message.id !== undefined && message.method === undefined) {
        inflight.delete(message.id)
        if (message.result && message.result.capabilities && message.result.capabilities.tools) listChanged = message.result.capabilities.tools.listChanged === true
      }
      toClient(line)
      void maybeSwap()
    })
    if (replay && initialize) {
      swapping = true
      toChild(JSON.stringify({ ...initialize, id: REPLAY }))
    }
  }

  // Once current.json names another version, new requests wait for the swap instead of reaching a server whose relay is
  // going away (or already runs the other version); a switch that doesn't happen releases them.
  let heldSince
  const moved = () => { try { return current() !== version } catch { return false } }
  const fromClient = (line) => {
    const message = parse(line)
    // A cancellation drops the request at once, even while client messages wait: it may be the one blocking the swap.
    if (message && message.method === "notifications/cancelled") trackRequest(message)
    if (swapping) return void queue.push(line)
    if (moved()) {
      heldSince ??= Date.now()
      queue.push(line)
      return void maybeSwap()
    }
    if (message && message.method === "initialize") initialize = message
    if (message && message.method === "notifications/initialized") initialized = line
    forward(line)
  }

  // A new version in current.json swaps the server only once the relay runs it too (GET /version), so a server never
  // talks to a relay of another version. With no relay at all for a few checks, nothing can mix, and it swaps.
  let checking = false
  let unreachable = 0
  const relayVersion = () => fetch("http://127.0.0.1:" + relayPort + "/version", { signal: AbortSignal.timeout(2000) })
    .then((response) => (response.ok ? response.json() : undefined))
    .then((body) => (body && typeof body.version === "string" ? body.version : undefined), () => undefined)
  const maybeSwap = async () => {
    if (swapping || checking) return
    // Held requests go to the current server at the deadline even when a request still looks in flight: a cancelled
    // request may never answer, and waiting for it would wedge the swap forever.
    if (heldSince !== undefined && Date.now() - heldSince > 15000) {
      heldSince = undefined
      const released = queue.splice(0)
      for (const line of released) forward(line)
    }
    if (inflight.size > 0) return
    let next
    try { next = current() } catch { return }
    if (next === version) {
      unreachable = 0
      heldSince = undefined
      for (const queued of queue.splice(0)) fromClient(queued)
      return
    }
    checking = true
    const running = await relayVersion()
    checking = false
    unreachable = running === undefined ? unreachable + 1 : 0
    // Held requests don't wait forever for a relay that never reports the new version: they go to the current server.
    if (running !== next && unreachable < 3) return
    if (swapping || inflight.size > 0 || current() !== next) return
    const old = child
    version = next
    heldSince = undefined
    start(true)
    old.stdin.end()
    setTimeout(() => old.kill(), 5000).unref()
  }

  start(false)
  createInterface({ input: process.stdin }).on("line", fromClient).on("close", () => {
    child.stdin.end()
    setTimeout(() => process.exit(0), 5000).unref()
  })
  setInterval(() => void maybeSwap(), 1000).unref()
}
